import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Search, BookOpen, Sparkles } from 'lucide-react';
import { motion } from 'framer-motion';

const HeroSection = ({ settings }) => {
    const [searchQuery, setSearchQuery] = useState('');
    const navigate = useNavigate();

    const bannerText = settings?.homepageBannerText || 'Welcome to Bookverse';

    const handleSearch = (e) => {
        e.preventDefault();
        if (searchQuery.trim()) {
            navigate(`/explore?q=${encodeURIComponent(searchQuery)}`);
        }
    };

    return (
        <div className="relative overflow-hidden rounded-3xl mb-12">
            {/* Background Gradient & Pattern */}
            <div className="absolute inset-0 bg-gradient-bookverse opacity-90"></div>
            <div className="absolute inset-0 opacity-10" style={{ backgroundImage: 'radial-gradient(circle at 2px 2px, white 1px, transparent 0)', backgroundSize: '24px 24px' }}></div>

            {/* Floating Elements for Visual Interest */}
            <div className="absolute top-10 right-10 animate-float opacity-20 hidden md:block">
                <BookOpen size={120} className="text-white" />
            </div>
            <div className="absolute -bottom-10 -left-10 animate-float opacity-20 hidden md:block" style={{ animationDelay: '1.5s' }}>
                <Sparkles size={160} className="text-white" />
            </div>

            <div className="relative px-8 py-6 md:py-10 flex flex-col items-center text-center max-w-4xl mx-auto">
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="inline-block px-3 py-0.5 rounded-full bg-white/10 text-white text-[9px] font-black uppercase tracking-[0.2em] mb-3 backdrop-blur-md border border-white/10"
                >
                    {bannerText}
                </motion.div>

                <motion.h1
                    initial={{ opacity: 0, y: 15 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="text-2xl md:text-4xl font-serif font-black text-white mb-3 leading-tight tracking-tight px-4"
                >
                    Your Personal Library, <br />
                    <span className="text-transparent bg-clip-text bg-gradient-to-r from-teal-200 to-emerald-200 italic">Reimagined.</span>
                </motion.h1>

                <motion.p
                    initial={{ opacity: 0, y: 15 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="text-sm md:text-base text-teal-50/70 mb-6 max-w-lg leading-snug px-6"
                >
                    Discover millions of books and track your progress in your own sanctuary.
                </motion.p>

                {/* Search Container */}
                <form onSubmit={handleSearch} className="w-full max-w-lg relative group">
                    <div className="absolute inset-0 bg-teal-500/20 blur-xl opacity-0 group-focus-within:opacity-100 transition-opacity duration-700 rounded-full pointer-events-none"></div>
                    <div className="relative flex items-center bg-white/95 dark:bg-stone-900/95 backdrop-blur-xl rounded-xl p-1 shadow-2xl border border-white/20">
                        <div className="pl-3 text-teal-600/50">
                            <Search size={18} />
                        </div>
                        <input
                            type="text"
                            placeholder="Search by title, author, or genre..."
                            className="flex-1 bg-transparent border-none focus:ring-0 text-ink-900 dark:text-white px-2 py-1.5 text-sm placeholder:text-ink-400"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                        <button
                            type="submit"
                            className="bg-teal-600 hover:bg-teal-700 text-white px-5 py-2 rounded-lg font-bold transition-all shadow-lg active:scale-95 text-xs"
                        >
                            Search
                        </button>
                    </div>

                    {/* Quick Tags */}
                    <div className="mt-4 flex flex-wrap justify-center gap-4 text-[10px] font-black relative">
                        <span className="text-teal-200/20 uppercase tracking-[0.2em]">Quick Search:</span>
                        {(settings?.featuredCategories?.length > 0 ? settings.featuredCategories.slice(0, 4) : ['Fiction', 'Sci-Fi', 'Mystery', 'History']).map((tag) => (
                            <Link
                                key={tag}
                                to={`/explore?q=${encodeURIComponent(tag)}`}
                                className="text-white/40 hover:text-teal-300 transition-all uppercase tracking-[0.15em] border-b border-white/10 hover:border-teal-400/50 pb-0.5 hover:-translate-y-0.5"
                            >
                                {tag}
                            </Link>
                        ))}
                    </div>
                </form>
            </div>
        </div>
    );
};

export default HeroSection;

import React, { useMemo } from 'react';
import { Link } from 'react-router-dom';
import { BookOpen, Trophy, Target, ArrowRight, Heart } from 'lucide-react';
import { useAuthStore } from '../store/authStore';
import { useQuery } from '@tanstack/react-query';
import { getFavoriteBooks } from '../services/bookService';
import { getMyLists } from '../services/listService';

const HomeSidebar = () => {
    const { user } = useAuthStore();

    const { data: favoriteBooks } = useQuery({
        queryKey: ['favoriteBooks'],
        queryFn: getFavoriteBooks,
        enabled: !!user
    });

    const { data: myLists } = useQuery({
        queryKey: ['myLists'],
        queryFn: getMyLists,
        enabled: !!user
    });

    // Derive "Currently Reading" from lists
    const currentRead = useMemo(() => {
        if (!myLists) return null;
        // Find a book with status READING
        const readingItem = myLists.find(item => item.status === 'READING');
        if (!readingItem) return null;

        // Find details in savedBooks (or we might need to fetch if list item doesn't have full details)
        // List item usually has googleBookId.
        // Let's try to match with savedBooks to get cover/title if list item is sparse.
        // Assuming list item has some info or we use savedBooks to find it.
        // Actually myLists items usually have googleBookId.
        // Let's find the favorite book.
        return favoriteBooks?.find(b => b.googleBookId === readingItem.googleBookId);
    }, [myLists, favoriteBooks]);

    // Derive Challenge Progress (Completed this year)
    const challengeProgress = useMemo(() => {
        if (!myLists) return 0;
        const currentYear = new Date().getFullYear();
        return myLists.filter(item =>
            item.status === 'COMPLETED' &&
            new Date(item.updatedAt || Date.now()).getFullYear() === currentYear
        ).length;
    }, [myLists]);

    if (!user) {
        return (
            <div className="space-y-6">
                <div className="card-libra p-6 text-center">
                    <h3 className="font-bold font-serif text-ink-900 text-lg mb-2">New here?</h3>
                    <p className="text-sm text-ink-600 mb-4">Create a free account to track your reading and discover new books.</p>
                    <Link to="/register" className="btn-primary block w-full text-center mb-2">Create Account</Link>
                    <p className="text-xs text-ink-400">Already a member? <Link to="/login" className="text-teal-600 hover:underline">Sign in</Link></p>
                </div>
            </div>
        );
    }

    return (
        <aside className="space-y-6">
            {/* 1. Currently Reading (Real) */}
            {currentRead ? (
                <div className="card-libra p-4">
                    <h3 className="font-bold text-ink-900 text-sm border-b border-paper-200 pb-2 mb-3 uppercase tracking-wider">
                        Currently Reading
                    </h3>

                    <div className="flex gap-3">
                        <div className="w-16 h-24 bg-paper-200 shrink-0 rounded shadow-sm border border-paper-200 overflow-hidden">
                            <img src={currentRead.thumbnail || "https://via.placeholder.com/64x96?text=No+Cover"} alt={currentRead.title} className="w-full h-full object-cover" />
                        </div>
                        <div className="flex-1 min-w-0">
                            <Link to={`/book/${currentRead.googleBookId}`} className="font-bold text-sm text-ink-900 hover:underline truncate block">{currentRead.title}</Link>
                            <p className="text-xs text-ink-600 mb-2">{currentRead.authors?.[0]}</p>

                            <div className="space-y-1">
                                <div className="w-full bg-paper-200 h-1.5 rounded-full overflow-hidden">
                                    <div className="bg-teal-600 h-1.5 rounded-full" style={{ width: '0%' }}></div> {/* TODO: Add progress page logic */}
                                </div>
                                <div className="flex justify-between text-[10px] text-ink-400 font-medium">
                                    <span>Track Progress &rarr;</span>
                                </div>
                            </div>

                            <Link to="/dashboard" className="text-[10px] font-bold text-teal-600 hover:underline mt-2 block">
                                Update Progress
                            </Link>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="card-libra p-4 border-dashed">
                    <h3 className="font-bold text-ink-900 text-sm mb-2">No active read</h3>
                    <p className="text-xs text-ink-500 mb-3">Start a book to track your progress here.</p>
                    <Link to="/discover" className="btn-outline w-full text-center text-xs py-1.5">Find a Book</Link>
                </div>
            )}

            {/* 2. Reading Challenge (Dynamic) */}
            <div className="card-libra p-4">
                <h3 className="font-bold text-ink-900 text-sm border-b border-paper-200 pb-2 mb-3 uppercase tracking-wider">
                    {new Date().getFullYear()} Challenge
                </h3>
                <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-full border-4 border-paper-200 flex items-center justify-center relative shrink-0">
                        <span className="text-xs font-bold text-ink-900">{challengeProgress}</span>
                    </div>
                    <div>
                        <p className="text-sm font-bold text-ink-900">You have read {challengeProgress} book{challengeProgress !== 1 && 's'}!</p>
                        <p className="text-xs text-ink-600">Keep going to reach your goal.</p>
                        <Link to="/challenges" className="text-xs text-teal-600 font-bold hover:underline mt-1 block">View Challenge</Link>
                    </div>
                </div>
            </div>

            {/* 3. Favorites Link */}
            <div className="card-libra p-4">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <Heart size={20} className="text-rose-500 fill-rose-500" />
                        <h3 className="font-bold text-ink-900 text-sm uppercase tracking-wider">Favorites</h3>
                    </div>
                    <Link to="/favorites" className="text-xs text-teal-600 font-bold hover:underline">View All</Link>
                </div>
                {favoriteBooks && favoriteBooks.length > 0 ? (
                    <div className="mt-3 flex -space-x-2">
                        {favoriteBooks.slice(0, 5).map((book, i) => (
                            <Link key={book._id} to={`/book/${book.googleBookId}`} title={book.title}>
                                <img
                                    src={book.thumbnail || "https://via.placeholder.com/32x48?text=?"}
                                    className="w-8 h-12 rounded border-2 border-white dark:border-stone-900 object-cover shadow-sm hover:-translate-y-1 transition-transform"
                                    alt={book.title}
                                />
                            </Link>
                        ))}
                    </div>
                ) : (
                    <p className="text-[10px] text-ink-500 mt-2">No favorites added yet.</p>
                )}
            </div>

            <div className="text-xs text-ink-400 text-center px-4">
                <p>&copy; 2026 Bookverse</p>
            </div>
        </aside>
    );
};

export default HomeSidebar;

import React from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../services/api';
import { Link } from 'react-router-dom';
import { Trash2, Star, Calendar } from 'lucide-react';
import { getBookDetails } from "../services/googleBooksService";
import toast from 'react-hot-toast';

const ListBookCard = ({ item, showRemove = true }) => {
    const queryClient = useQueryClient();

    const { data: bookDetails, isLoading } = useQuery({
        queryKey: ['book', item.googleBookId],
        queryFn: () => getBookDetails(item.googleBookId),
        staleTime: 1000 * 60 * 60,
    });

    const removeMutation = useMutation({
        mutationFn: async () => {
            await api.delete(`/lists/remove/${item.googleBookId}`);
        },
        onMutate: async () => {
            // Cancel any outgoing refetches
            await queryClient.cancelQueries({ queryKey: ['myLists'] });

            // Snapshot the previous value
            const previousLists = queryClient.getQueryData(['myLists']);

            // Optimistically update to the new value
            queryClient.setQueryData(['myLists'], (old) => old?.filter(b => b.googleBookId !== item.googleBookId));

            return { previousLists };
        },
        onSuccess: () => {
            toast.success('Removed from shelf');
        },
        onError: (err, variables, context) => {
            toast.error('Action failed');
            if (context?.previousLists) {
                queryClient.setQueryData(['myLists'], context.previousLists);
            }
        },
        onSettled: () => {
            queryClient.invalidateQueries({ queryKey: ['myLists'] });
        }
    });

    if (isLoading) return <div className="h-16 bg-paper-100 dark:bg-stone-900 rounded animate-pulse my-2"></div>;
    if (!bookDetails) return null;

    const { title, authors, imageLinks, averageRating, ratingsCount } = bookDetails.volumeInfo;
    const thumbnail = imageLinks?.thumbnail?.replace('http:', 'https:') || 'https://via.placeholder.com/90x140';

    return (
        <div className="flex items-center gap-4 py-3 border-b border-paper-200 dark:border-stone-800 hover:bg-paper-50 dark:hover:bg-stone-900/50 transition-colors group">
            {/* 1. Cover */}
            <Link to={`/book/${item.googleBookId}`} className="shrink-0 w-14 h-20 shadow-md group-hover:shadow-xl transition-shadow rounded overflow-hidden border border-paper-200 dark:border-stone-800 bg-paper-100 dark:bg-stone-800 relative">
                <img
                    src={thumbnail}
                    alt={title}
                    className="w-full h-full object-cover"
                    onError={(e) => {
                        e.target.onerror = null;
                        e.target.src = 'https://via.placeholder.com/90x140?text=No+Cover';
                    }}
                />
            </Link>

            {/* 2. Title & Author (Main Col) */}
            <div className="flex-1 min-w-0 grid grid-cols-1 md:grid-cols-12 gap-4 items-center">
                <div className="md:col-span-5">
                    <Link to={`/book/${item.googleBookId}`} className="font-bold text-ink-900 dark:text-stone-100 hover:text-teal-600 dark:hover:text-teal-400 transition-colors leading-tight block serif text-base">
                        {title}
                    </Link>
                    <p className="text-sm text-ink-500 dark:text-stone-500 mt-0.5">by <span className="font-medium text-ink-700 dark:text-stone-300">{authors?.join(', ')}</span></p>
                </div>

                {/* 3. Rating */}
                <div className="md:col-span-3 hidden md:flex items-center gap-1">
                    <div className="flex text-amber-500 text-xs">
                        {[...Array(5)].map((_, i) => (
                            <Star key={i} size={14} fill={i < Math.round(averageRating || 0) ? "currentColor" : "none"} />
                        ))}
                    </div>
                    <span className="text-xs text-ink-400 dark:text-stone-500">({ratingsCount || 0})</span>
                </div>

                {/* 4. Date Added / Empty Slot */}
                <div className="md:col-span-3 hidden md:flex items-center gap-2 text-xs text-ink-400 dark:text-stone-500">
                    <Calendar size={14} />
                    <span>{new Date(item.updatedAt || Date.now()).toLocaleDateString()}</span>
                </div>

                {/* 5. Actions */}
                <div className="md:col-span-1 flex justify-end">
                    {showRemove && (
                        <button
                            onClick={() => removeMutation.mutate()}
                            className="p-2.5 text-ink-400 dark:text-stone-600 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/10 rounded-full transition-all opacity-0 group-hover:opacity-100 hover:scale-110 active:scale-95"
                            title="Remove from shelf"
                        >
                            <Trash2 size={18} />
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ListBookCard;

import React, { useState } from 'react';
import { Link, NavLink, useNavigate } from 'react-router-dom';
import { useAuthStore } from '../store/authStore';
import { BookOpen, Menu, X, User, Sun, Moon } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useThemeStore } from '../store/themeStore';

const Navbar = () => {
    const { user, logout } = useAuthStore();
    const { isDarkMode, toggleDarkMode } = useThemeStore();
    const navigate = useNavigate();
    const [isOpen, setIsOpen] = useState(false);
    const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);

    const handleLogout = () => {
        logout();
        setIsUserMenuOpen(false);
        navigate('/login');
    };
    const navLinks = [
        { path: '/', label: 'Home', auth: true },
        { path: '/discover', label: 'Discover', auth: false },
        { path: '/recommendations', label: 'Recommendations', auth: true },
        { path: '/favorites', label: 'Favorites', auth: true },
        { path: '/my-books', label: 'My Books', auth: true },
        { path: '/explore', label: 'Browse', auth: false },
    ];

    return (
        <nav className="fixed top-0 left-0 w-full z-50 bg-white border-b border-paper-200 transition-colors duration-300 dark:bg-stone-900 dark:border-stone-800">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-12">
                <div className="flex items-center justify-between h-full">

                    {/* Left: Logo & Nav */}
                    <div className="flex items-center gap-8">
                        <Link to="/" className="flex items-center gap-2 group">
                            <div className="p-1 bg-teal-600 rounded text-white">
                                <BookOpen size={18} fill="currentColor" />
                            </div>
                            <span className="text-xl font-bold font-serif text-ink-900 dark:text-stone-100 tracking-tight">Bookverse</span>
                        </Link>

                        {/* Desktop Nav */}
                        <div className="hidden lg:flex items-center space-x-6">
                            {navLinks.map(link => (!link.auth || user) && (
                                <NavLink
                                    key={link.path}
                                    to={link.path}
                                    className={({ isActive }) => `text-sm font-medium transition-colors border-b-2 py-5 ${isActive ? 'text-ink-900 border-teal-600 dark:text-stone-100' : 'text-ink-600 border-transparent hover:text-teal-600 dark:text-stone-400 dark:hover:text-teal-500'}`}
                                >
                                    {link.label}
                                </NavLink>
                            ))}
                        </div>
                    </div>

                    {/* Right: User Menu & Theme Toggle */}
                    <div className="hidden lg:flex items-center gap-4">
                        <button
                            onClick={toggleDarkMode}
                            className="p-2 rounded-full hover:bg-paper-100 transition-colors text-ink-600 dark:text-stone-400 dark:hover:bg-stone-800"
                            title={isDarkMode ? 'Light Mode' : 'Dark Mode'}
                        >
                            {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
                        </button>

                        {user ? (
                            <div className="relative">
                                <button
                                    onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
                                    className={`flex items-center gap-3 rounded-full p-1.5 pr-4 transition-all border ${user.role === 'ADMIN' ? 'bg-teal-50/80 border-teal-200 dark:bg-teal-900/20 dark:border-teal-800' : 'hover:bg-paper-100 dark:hover:bg-stone-800 border-transparent'}`}
                                >
                                    <div className={`w-8 h-8 rounded-full bg-paper-200 dark:bg-stone-800 overflow-hidden border transition-all ${user.role === 'ADMIN' ? 'border-teal-500 shadow-[0_0_15px_rgba(20,184,166,0.3)]' : 'border-paper-300 dark:border-stone-700'}`}>
                                        {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover" alt="" /> : <User size={20} strokeWidth={2.5} className="text-ink-400 dark:text-stone-500" />}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span className="text-sm font-bold text-ink-900 dark:text-stone-100">{user.name.split(' ')[0]}</span>
                                        {user.role === 'ADMIN' && (
                                            <span className="px-1.5 py-0.5 bg-teal-600 text-white text-[9px] font-black rounded uppercase tracking-widest shadow-sm">Admin</span>
                                        )}
                                    </div>
                                </button>

                                <AnimatePresence>
                                    {isUserMenuOpen && (
                                        <>
                                            <div className="fixed inset-0 z-10" onClick={() => setIsUserMenuOpen(false)} />
                                            <motion.div
                                                initial={{ opacity: 0, y: 10 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                exit={{ opacity: 0, y: 10 }}
                                                className="absolute top-full right-0 mt-2 w-56 bg-white border border-paper-200 rounded shadow-card z-20 py-2 dark:bg-stone-900 dark:border-stone-800"
                                            >
                                                <div className="px-4 py-2 border-b border-paper-100 mb-2 dark:border-stone-800 flex justify-between items-start">
                                                    <div>
                                                        <p className="font-bold text-ink-900 text-sm dark:text-stone-100">{user.name}</p>
                                                        <p className="text-xs text-ink-400 dark:text-stone-500">@{user.username}</p>
                                                    </div>
                                                    {user.role === 'ADMIN' && (
                                                        <span className="px-1.5 py-0.5 bg-teal-100 dark:bg-teal-900 text-teal-700 dark:text-teal-400 text-[8px] font-black rounded uppercase tracking-wider border border-teal-200 dark:border-teal-800">Admin</span>
                                                    )}
                                                </div>

                                                <Link to="/profile" className="block px-4 py-2 text-sm text-ink-600 hover:bg-paper-50 hover:text-teal-600 dark:text-stone-400 dark:hover:bg-stone-800 dark:hover:text-teal-500">Profile</Link>
                                                {user.role === 'ADMIN' && (
                                                    <Link to="/admin/dashboard" className="block px-4 py-2 text-sm text-ink-600 hover:bg-paper-50 hover:text-teal-600 dark:text-stone-400 dark:hover:bg-stone-800 dark:hover:text-teal-500">Admin Dashboard</Link>
                                                )}
                                                <div className="border-t border-paper-100 my-2 dark:border-stone-800" />
                                                <button onClick={handleLogout} className="w-full text-left px-4 py-2 text-sm text-ink-600 hover:bg-paper-50 hover:text-teal-600 dark:text-stone-400 dark:hover:bg-stone-800 dark:hover:text-teal-500">Sign Out</button>
                                            </motion.div>
                                        </>
                                    )}
                                </AnimatePresence>
                            </div>
                        ) : (
                            <div className="flex items-center gap-3">
                                <Link to="/login" className="text-sm font-bold text-ink-600 hover:text-teal-600 dark:text-stone-400 dark:hover:text-teal-500">Log In</Link>
                                <Link to="/register" className="btn-primary text-sm py-1.5 px-4 rounded-full">Sign Up</Link>
                            </div>
                        )}
                    </div>

                    {/* Mobile Menu Toggle */}
                    <button onClick={() => setIsOpen(!isOpen)} className="lg:hidden p-2 text-ink-600 dark:text-stone-400">
                        {isOpen ? <X size={24} /> : <Menu size={24} />}
                    </button>
                </div>
            </div>

            {/* Mobile Menu */}
            {isOpen && (
                <div className="lg:hidden bg-white dark:bg-stone-900 border-b border-paper-200 dark:border-stone-800 px-4 py-4 space-y-4">
                    {navLinks.map(link => (!link.auth || user) && (
                        <Link key={link.path} to={link.path} onClick={() => setIsOpen(false)} className="block py-2 text-ink-600 font-medium border-b border-paper-100 dark:text-stone-400 dark:border-stone-800">
                            {link.label}
                        </Link>
                    ))}
                    {user ? (
                        <>
                            <Link to="/profile" onClick={() => setIsOpen(false)} className="block py-2 text-ink-600 font-medium">Profile</Link>
                            <button onClick={handleLogout} className="block w-full text-left py-2 text-ink-600 font-medium">Sign Out</button>
                        </>
                    ) : (
                        <div className="flex gap-4 pt-2">
                            <Link to="/login" className="flex-1 btn-ghost text-center text-sm border border-paper-200">Log In</Link>
                            <Link to="/register" className="flex-1 btn-primary text-center text-sm">Sign Up</Link>
                        </div>
                    )}
                </div>
            )}
        </nav>
    );
};

export default Navbar;

messages.message:
Error: Calling setState synchronously within an effect can trigger cascading renders

Effects are intended to synchronize state between React and external systems such as manually updating the DOM, state management libraries, or other platform APIs. In general, the body of an effect should do one or both of the following:
* Update external systems with the latest state from React.
* Subscribe for updates from some external system, calling setState in a callback function when external state changes.

Calling setState synchronously within an effect body causes cascading renders that can hurt performance, and is not recommended. (https://react.dev/learn/you-might-not-need-an-effect).

