import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Save, BookOpen } from 'lucide-react';

const ReadingProgressModal = ({ isOpen, onClose, book, onUpdate }) => {
    // Detect structure: Google API (volumeInfo) vs Flattened
    const title = book?.volumeInfo?.title || book?.title || 'Unknown Title';
    const authors = book?.volumeInfo?.authors || book?.authors || [];
    const cover = book?.volumeInfo?.imageLinks?.thumbnail || book?.coverImage || book?.thumbnail || 'https://via.placeholder.com/96x144?text=No+Cover';

    const [currentPage, setCurrentPage] = useState(book?.currentPage || 0);
    const [localTotalPages, setLocalTotalPages] = useState(book?.volumeInfo?.pageCount || book?.pageCount || 100);

    // Synchronize state when book prop changes or modal opens
    useEffect(() => {
        if (isOpen) {
            setCurrentPage(book?.currentPage || 0);
            setLocalTotalPages(book?.volumeInfo?.pageCount || book?.pageCount || 100);
        }
    }, [isOpen, book?.currentPage, book?.pageCount, book?.googleBookId]);

    // Calculate percentage
    const percentage = Math.round((currentPage / (localTotalPages || 1)) * 100);

    const handleSubmit = (e) => {
        e.preventDefault();
        onUpdate(currentPage, localTotalPages);
        onClose();
    };

    return (
        <AnimatePresence>
            {isOpen && (
                <>
                    {/* Backdrop */}
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="fixed inset-0 bg-ink-900/40 backdrop-blur-sm z-50 transition-opacity"
                    />

                    {/* Modal */}
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 10 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 10 }}
                        className="fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-full max-w-md bg-white dark:bg-stone-900 rounded-2xl shadow-2xl p-6 z-50 border border-paper-100 dark:border-stone-800"
                    >
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-bold font-serif text-ink-900 dark:text-stone-100 flex items-center gap-2">
                                <BookOpen size={20} className="text-teal-600" />
                                Update Progress
                            </h3>
                            <button onClick={onClose} className="text-ink-400 hover:text-ink-600 dark:text-stone-500 dark:hover:text-stone-300 transition-colors">
                                <X size={20} />
                            </button>
                        </div>

                        <div className="mb-6 flex gap-4 items-center p-3 bg-paper-50 dark:bg-stone-800/50 rounded-xl border border-paper-100 dark:border-stone-800">
                            <div className="w-12 h-18 bg-paper-100 dark:bg-stone-800 rounded border border-paper-200 dark:border-stone-700 shrink-0 overflow-hidden shadow-sm">
                                <img
                                    src={cover}
                                    alt={title}
                                    className="w-full h-full object-cover"
                                />
                            </div>
                            <div className="min-w-0">
                                <h4 className="font-bold text-ink-900 dark:text-stone-100 line-clamp-1 text-sm">{title}</h4>
                                <p className="text-xs text-ink-500 dark:text-stone-400 mb-1 truncate">
                                    {Array.isArray(authors) ? authors.join(', ') : (authors || 'Unknown Author')}
                                </p>
                                <div className="text-[10px] font-bold text-teal-600 bg-teal-50 dark:bg-teal-900/30 dark:text-teal-400 px-2 py-0.5 rounded-full inline-block uppercase tracking-wider">
                                    Currently Reading
                                </div>
                            </div>
                        </div>

                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div>
                                <div className="flex justify-between text-xs font-bold text-ink-600 dark:text-stone-400 mb-3 uppercase tracking-wide">
                                    <span>Page {currentPage}</span>
                                    <span>{totalPages} pages ({percentage}%)</span>
                                </div>
                                <div className="relative h-2 w-full bg-paper-200 dark:bg-stone-800 rounded-full group">
                                    <input
                                        type="range"
                                        min="0"
                                        max={totalPages}
                                        value={currentPage}
                                        onChange={(e) => setCurrentPage(Number(e.target.value))}
                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                    />
                                    <div
                                        className="absolute top-0 left-0 h-full bg-teal-600 rounded-full transition-all duration-200"
                                        style={{ width: `${percentage}%` }}
                                    />
                                    <div
                                        className="absolute top-1/2 -translate-y-1/2 w-4 h-4 bg-white border-2 border-teal-600 rounded-full shadow-md transition-all duration-200 pointer-events-none"
                                        style={{ left: `calc(${percentage}% - 8px)` }}
                                    />
                                </div>
                                <div className="mt-8 flex gap-4">
                                    <div className="flex-1">
                                        <label className="block text-[10px] font-bold text-ink-400 dark:text-stone-500 uppercase tracking-widest mb-1.5 ml-1">
                                            Current Page
                                        </label>
                                        <input
                                            type="number"
                                            min="0"
                                            max={totalPages}
                                            value={currentPage}
                                            onChange={(e) => setCurrentPage(Number(e.target.value))}
                                            className="w-full input-libra py-2.5 px-4 text-sm font-bold focus:ring-teal-500"
                                            placeholder="0"
                                        />
                                    </div>
                                    <div className="flex-1">
                                        <label className="block text-[10px] font-bold text-ink-400 dark:text-stone-500 uppercase tracking-widest mb-1.5 ml-1">
                                            Total Pages
                                        </label>
                                        <input
                                            type="number"
                                            min="1"
                                            value={localTotalPages}
                                            onChange={(e) => setLocalTotalPages(Number(e.target.value))}
                                            className="w-full input-libra py-2.5 px-4 text-sm font-bold focus:ring-teal-500"
                                            placeholder="100"
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="flex justify-end gap-3 pt-6 border-t border-paper-100 dark:border-stone-800">
                                <button
                                    type="button"
                                    onClick={onClose}
                                    className="px-6 py-2.5 text-sm font-bold text-ink-500 dark:text-stone-400 hover:bg-paper-100 dark:hover:bg-stone-800 rounded-xl transition-colors"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    className="btn-primary px-10 py-2.5 flex items-center gap-2 transform active:scale-95 transition-all shadow-lg"
                                >
                                    <Save size={18} /> Update
                                </button>
                            </div>
                        </form>
                    </motion.div>
                </>
            )}
        </AnimatePresence>
    );
};

export default ReadingProgressModal;

import React, { useState } from 'react';
import ReviewItem from './ReviewItem';
import { Star, Send } from 'lucide-react';
import { useAuthStore } from '../store/authStore';

const ReviewList = ({ reviews, user, onAddReview, onDeleteReview }) => {
    const [reviewText, setReviewText] = useState('');
    const [rating, setRating] = useState(0);

    const handleSubmit = () => {
        if (reviewText.trim() && rating > 0) {
            onAddReview({ rating, reviewText });
            setReviewText('');
            setRating(0);
        }
    };

    return (
        <div className="max-w-4xl">
            {/* Header */}
            <div className="flex items-center justify-between border-b border-paper-200 dark:border-stone-800 pb-4 mb-8">
                <h3 className="text-xl font-bold font-serif text-ink-900 dark:text-stone-100">
                    Community Reviews
                    <span className="ml-2 text-sm font-sans font-normal text-ink-500 dark:text-stone-400 bg-paper-100 dark:bg-stone-800 px-2 py-0.5 rounded-full">
                        {reviews.length}
                    </span>
                </h3>
            </div>

            {/* Input Area */}
            {user && (
                <div className="mb-10 flex gap-4 bg-paper-100/50 dark:bg-stone-900/50 p-6 rounded-xl border border-paper-200 dark:border-stone-800">
                    <div className="shrink-0">
                        <div className="w-10 h-10 rounded-full bg-teal-100 dark:bg-teal-900/30 flex items-center justify-center text-teal-800 dark:text-teal-400 font-bold border border-teal-200 dark:border-teal-800">
                            {user.name?.charAt(0)}
                        </div>
                    </div>
                    <div className="flex-1 space-y-3">
                        <textarea
                            className="w-full input-libra dark:bg-stone-800 dark:text-stone-100 dark:border-stone-700 rounded-lg p-3 text-sm min-h-[100px] resize-none"
                            placeholder="Share your thoughts on this book..."
                            value={reviewText}
                            onChange={e => setReviewText(e.target.value)}
                        />
                        <div className="flex justify-between items-center">
                            <div className="flex items-center gap-2">
                                <span className="text-xs font-bold text-ink-400 dark:text-stone-500 uppercase tracking-wider mr-2">Your Rating:</span>
                                {[1, 2, 3, 4, 5].map(s => (
                                    <button
                                        key={s}
                                        onClick={() => setRating(s)}
                                        className={`transition-all hover:scale-110 ${s <= rating ? "text-amber-400" : "text-ink-400/30 dark:text-stone-700 hover:text-amber-200"}`}
                                    >
                                        <Star size={20} fill="currentColor" />
                                    </button>
                                ))}
                            </div>
                            <button
                                onClick={handleSubmit}
                                disabled={!rating || !reviewText.trim()}
                                className="px-5 py-2 btn-primary text-xs font-bold rounded-full disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                            >
                                <Send size={14} /> Post Review
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* List */}
            <div className="space-y-4">
                {reviews.length > 0 ? (
                    reviews.map(rev => (
                        <ReviewItem
                            key={rev._id}
                            review={rev}
                            currentUser={user}
                            onDelete={onDeleteReview}
                        />
                    ))
                ) : (
                    <div className="text-center py-12 bg-paper-50 dark:bg-stone-900/50 rounded-lg border border-dashed border-paper-200 dark:border-stone-800">
                        <p className="text-ink-500 dark:text-stone-400 italic font-serif">No reviews yet.</p>
                        <p className="text-xs text-ink-400 dark:text-stone-500 mt-1">Be the first to share your opinion!</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default ReviewList;

import React from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../services/api';
import { Loader2, Trash2, Ban, CheckCircle, TrendingUp, Star, Heart, MessageSquare, Settings as SettingsIcon, BookOpen } from 'lucide-react';
import toast from 'react-hot-toast';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, LineChart, Line, CartesianGrid, Legend } from 'recharts';

const AdminDashboard = () => {
    const queryClient = useQueryClient();
    const [activeTab, setActiveTab] = React.useState('stats');

    const { data: users, isLoading: isLoadingUsers } = useQuery({
        queryKey: ['users'],
        queryFn: async () => {
            const res = await api.get('/admin/users');
            return res.data;
        }
    });

    const { data: stats, isLoading: isLoadingStats } = useQuery({
        queryKey: ['adminStats'],
        queryFn: async () => {
            const res = await api.get('/admin/stats');
            return res.data;
        }
    });

    const { data: allReviews, isLoading: isLoadingReviews } = useQuery({
        queryKey: ['allReviews'],
        queryFn: async () => {
            const res = await api.get('/admin/reviews');
            return res.data;
        },
        enabled: activeTab === 'reviews'
    });


    const [settingsData, setSettingsData] = React.useState({
        featuredCategories: '',
        homepageBannerText: ''
    });

    const { data: settings } = useQuery({
        queryKey: ['adminSettings'],
        queryFn: async () => {
            const res = await api.get('/admin/settings');
            setSettingsData({
                featuredCategories: res.data.featuredCategories?.join(', ') || '',
                homepageBannerText: res.data.homepageBannerText || ''
            });
            return res.data;
        }
    });

    const banMutation = useMutation({
        mutationFn: async (userId) => {
            await api.put(`/admin/ban/${userId}`);
        },
        onSuccess: () => {
            toast.success('User status updated');
            queryClient.invalidateQueries({ queryKey: ['users'] });
        }
    });

    const deleteMutation = useMutation({
        mutationFn: async (userId) => {
            await api.delete(`/admin/delete-user/${userId}`);
        },
        onSuccess: () => {
            toast.success('User deleted');
            queryClient.invalidateQueries({ queryKey: ['users'] });
        }
    });

    const deleteReviewMutation = useMutation({
        mutationFn: async (reviewId) => {
            await api.delete(`/reviews/delete/${reviewId}`);
        },
        onSuccess: () => {
            toast.success('Review deleted');
            queryClient.invalidateQueries({ queryKey: ['allReviews'] });
            queryClient.invalidateQueries({ queryKey: ['adminStats'] });
        }
    });

    const updateSettingsMutation = useMutation({
        mutationFn: async (newData) => {
            await api.put('/admin/settings', newData);
        },
        onSuccess: () => {
            toast.success('Settings updated');
            queryClient.invalidateQueries({ queryKey: ['adminSettings'] });
        }
    });

    const COLORS = ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899'];

    if (isLoadingUsers || isLoadingStats) return <div className="flex justify-center py-20"><Loader2 className="animate-spin text-blue-600 w-10 h-10" /></div>;

    return (
        <div className="space-y-8 pb-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h1 className="text-3xl font-bold text-ink-900 serif">Admin Dashboard</h1>
                <div className="flex bg-paper-100 p-1 rounded-xl overflow-x-auto">
                    <button
                        onClick={() => setActiveTab('stats')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap ${activeTab === 'stats' ? 'bg-white dark:bg-stone-800 text-teal-600 shadow-sm' : 'text-ink-600 hover:text-ink-900'}`}
                    >
                        Analytics
                    </button>
                    <button
                        onClick={() => setActiveTab('users')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap ${activeTab === 'users' ? 'bg-white dark:bg-stone-800 text-teal-600 shadow-sm' : 'text-ink-600 hover:text-ink-900'}`}
                    >
                        Users
                    </button>
                    <button
                        onClick={() => setActiveTab('reviews')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap ${activeTab === 'reviews' ? 'bg-white dark:bg-stone-800 text-teal-600 shadow-sm' : 'text-ink-600 hover:text-ink-900'}`}
                    >
                        Moderation
                    </button>
                    <button
                        onClick={() => setActiveTab('settings')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition whitespace-nowrap ${activeTab === 'settings' ? 'bg-white dark:bg-stone-800 text-teal-600 shadow-sm' : 'text-ink-600 hover:text-ink-900'}`}
                    >
                        Settings
                    </button>
                </div>
            </div>

            {activeTab === 'stats' && (
                <div className="space-y-8 animate-in fade-in duration-500">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="card-libra p-6 flex items-center space-x-4">
                            <div className="p-4 bg-teal-50 dark:bg-teal-900/30 text-teal-600 rounded-2xl">
                                <TrendingUp size={24} />
                            </div>
                            <div>
                                <h3 className="text-ink-600 font-medium text-sm">Total Users</h3>
                                <p className="text-2xl font-bold text-ink-900">{stats?.summary?.users || 0}</p>
                            </div>
                        </div>
                        <div className="card-libra p-6 flex items-center space-x-4">
                            <div className="p-4 bg-red-50 dark:bg-red-900/30 text-red-600 rounded-2xl">
                                <Heart size={24} />
                            </div>
                            <div>
                                <h3 className="text-ink-600 font-medium text-sm">Favorite Books</h3>
                                <p className="text-2xl font-bold text-ink-900">{stats?.summary?.favoriteBooks || 0}</p>
                            </div>
                        </div>
                        <div className="card-libra p-6 flex items-center space-x-4">
                            <div className="p-4 bg-amber-50 dark:bg-amber-900/30 text-amber-600 rounded-2xl">
                                <MessageSquare size={24} />
                            </div>
                            <div>
                                <h3 className="text-ink-600 font-medium text-sm">Reviews</h3>
                                <p className="text-2xl font-bold text-ink-900">{stats?.summary?.reviews || 0}</p>
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                        <div className="lg:col-span-2 card-libra p-8">
                            <h3 className="text-xl font-bold text-ink-900 mb-6 font-serif">User Registration Growth</h3>
                            <div className="h-72">
                                <ResponsiveContainer width="100%" height="100%">
                                    <LineChart data={stats?.analytics?.growth}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                        <XAxis dataKey="_id" />
                                        <YAxis />
                                        <Tooltip />
                                        <Line type="monotone" dataKey="count" stroke="#3B82F6" strokeWidth={3} dot={{ r: 6 }} activeDot={{ r: 8 }} />
                                    </LineChart>
                                </ResponsiveContainer>
                            </div>
                        </div>


                        <div className="card-libra p-8">
                            <h3 className="text-xl font-bold text-ink-900 mb-6 font-serif">Genre Distribution</h3>
                            <div className="h-72">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={stats?.analytics?.categories}
                                            dataKey="count"
                                            nameKey="_id"
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={60}
                                            outerRadius={80}
                                            paddingAngle={5}
                                        >
                                            {stats?.analytics?.categories?.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <Tooltip />
                                        <Legend verticalAlign="bottom" height={36} />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        <div className="card-libra p-8">
                            <h3 className="text-xl font-bold text-ink-900 mb-6 font-serif">Top Search Keywords</h3>
                            <div className="h-64">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={stats?.analytics?.topKeywords.map(k => ({ name: k[0], count: k[1] }))}>
                                        <XAxis dataKey="name" stroke="currentColor" />
                                        <YAxis stroke="currentColor" />
                                        <Tooltip contentStyle={{ backgroundColor: 'var(--paper-100)', color: 'var(--ink-900)', border: 'none' }} />
                                        <Bar dataKey="count" fill="#14b8a6" radius={[4, 4, 0, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        <div className="card-libra p-8">
                            <h3 className="text-xl font-bold text-ink-900 mb-6 font-serif">Most Reviewed Books</h3>
                            <div className="space-y-4">
                                {stats?.analytics?.mostReviewed.map((book, i) => (
                                    <div key={book._id} className="flex items-center justify-between p-4 bg-paper-100 rounded-2xl">
                                        <div className="flex items-center space-x-3">
                                            <span className="w-8 h-8 flex items-center justify-center bg-paper-50 rounded-full font-bold text-teal-600 shadow-sm">{i + 1}</span>
                                            <span className="font-medium text-ink-900 truncate max-w-[200px]">{book._id}</span>
                                        </div>
                                        <span className="bg-teal-100 text-teal-800 px-3 py-1 rounded-full text-xs font-bold">{book.count} Reviews</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'users' && (
                <div className="card-libra overflow-hidden animate-in fade-in duration-500">
                    <div className="px-6 py-4 border-b border-paper-100 flex items-center justify-between">
                        <h2 className="text-xl font-bold text-ink-900">Manage Users</h2>
                        <span className="bg-teal-50 dark:bg-teal-900/30 text-teal-600 px-3 py-1 rounded-full text-xs font-bold">{users?.length} Total</span>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-paper-100 text-ink-600 text-sm">
                                <tr>
                                    <th className="px-6 py-3">User</th>
                                    <th className="px-6 py-3">Email</th>
                                    <th className="px-6 py-3">Role</th>
                                    <th className="px-6 py-3">Status</th>
                                    <th className="px-6 py-3 text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-paper-100">
                                {users?.map(user => (
                                    <tr key={user._id} className="hover:bg-paper-50 transition">
                                        <td className="px-6 py-4 font-medium text-ink-900 flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-full bg-teal-100 flex items-center justify-center text-teal-800 overflow-hidden shadow-inner border border-white dark:border-stone-800">
                                                {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover" alt="" /> : user.name.charAt(0)}
                                            </div>
                                            {user.name}
                                        </td>
                                        <td className="px-6 py-4 text-ink-600">{user.email}</td>
                                        <td className="px-6 py-4">
                                            <span className={`px-3 py-1 rounded-full text-xs font-bold ${user.role === 'ADMIN' ? 'bg-purple-100 text-purple-600' : 'bg-teal-100 text-teal-600'}`}>
                                                {user.role}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4">
                                            {user.isBanned ? (
                                                <span className="text-red-500 text-sm font-medium flex items-center gap-1"><Ban size={14} /> Banned</span>
                                            ) : (
                                                <span className="text-teal-500 text-sm font-medium flex items-center gap-1"><CheckCircle size={14} /> Active</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-right space-x-2">
                                            {user.role !== 'ADMIN' && (
                                                <div className="flex justify-end gap-2">
                                                    <button
                                                        onClick={() => banMutation.mutate(user._id)}
                                                        className={`p-2 rounded-xl transition ${user.isBanned ? 'text-green-600 bg-green-50 hover:bg-green-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}
                                                        title={user.isBanned ? "Unban User" : "Ban User"}
                                                    >
                                                        {user.isBanned ? <CheckCircle size={18} /> : <Ban size={18} />}
                                                    </button>
                                                    <button
                                                        onClick={() => {
                                                            if (confirm('Permanently delete this user?')) deleteMutation.mutate(user._id)
                                                        }}
                                                        className="p-2 text-red-600 bg-red-50 hover:bg-red-100 rounded-xl transition"
                                                        title="Delete User"
                                                    >
                                                        <Trash2 size={18} />
                                                    </button>
                                                </div>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {activeTab === 'reviews' && (
                <div className="card-libra overflow-hidden animate-in fade-in duration-500">
                    <div className="px-6 py-4 border-b border-paper-100 flex items-center justify-between">
                        <div className="flex items-center space-x-3">
                            <div className="p-2 bg-red-50 dark:bg-red-900/30 text-red-600 rounded-lg">
                                <MessageSquare size={20} />
                            </div>
                            <h2 className="text-xl font-bold text-ink-900">Review Moderation</h2>
                        </div>
                        <span className="bg-red-50 dark:bg-red-900/30 text-red-600 px-3 py-1 rounded-full text-xs font-bold">{allReviews?.length || 0} Total</span>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-paper-100 text-ink-600 text-sm">
                                <tr>
                                    <th className="px-6 py-3">User</th>
                                    <th className="px-6 py-3">Book</th>
                                    <th className="px-6 py-3 text-center">Rating</th>
                                    <th className="px-6 py-3">Comment</th>
                                    <th className="px-6 py-3 text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-paper-100">
                                {allReviews?.map(review => (
                                    <tr key={review._id} className="hover:bg-paper-50 transition align-top">
                                        <td className="px-6 py-4">
                                            <div className="text-sm font-bold text-ink-900">{review.userId?.name || 'Anonymous User'}</div>
                                            <div className="text-[10px] text-ink-400 font-mono select-all">UID: {review.userId?._id || review.userId}</div>
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="text-xs font-bold text-teal-600 uppercase tracking-wider">{review.googleBookId}</div>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <div className="inline-flex text-amber-500 gap-0.5">
                                                {[...Array(5)].map((_, i) => (
                                                    <Star key={i} size={12} fill={i < review.rating ? "currentColor" : "none"} />
                                                ))}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 max-w-xs">
                                            <p className="text-sm text-ink-700 dark:text-stone-300 leading-relaxed italic line-clamp-2" title={review.reviewText}>
                                                "{review.reviewText}"
                                            </p>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <button
                                                onClick={() => {
                                                    if (confirm('Delete this review permanently?')) deleteReviewMutation.mutate(review._id)
                                                }}
                                                className="p-2 text-red-600 bg-red-50 hover:bg-red-100 rounded-xl transition"
                                                title="Delete Review"
                                            >
                                                <Trash2 size={18} />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                        {(!allReviews || allReviews.length === 0) && !isLoadingReviews && (
                            <div className="py-20 text-center text-gray-500 italic">No reviews found for moderation.</div>
                        )}
                        {isLoadingReviews && <div className="flex justify-center py-10"><Loader2 className="animate-spin text-blue-600" /></div>}
                    </div>
                </div>
            )}


            {activeTab === 'settings' && (
                <div className="card-libra p-8 max-w-2xl animate-in fade-in duration-500">
                    <div className="flex items-center space-x-3 mb-6">
                        <div className="p-3 bg-teal-50 dark:bg-teal-900/30 text-teal-600 rounded-xl">
                            <SettingsIcon size={24} />
                        </div>
                        <h2 className="text-xl font-bold text-ink-900">Platform Portal Settings</h2>
                    </div>

                    <form className="space-y-6" onSubmit={(e) => {
                        e.preventDefault();
                        updateSettingsMutation.mutate({
                            featuredCategories: settingsData.featuredCategories.split(',').map(c => c.trim()).filter(c => c),
                            homepageBannerText: settingsData.homepageBannerText
                        });
                    }}>
                        <div>
                            <label className="block text-sm font-bold text-ink-600 mb-2 uppercase tracking-wide">Featured Categories</label>
                            <p className="text-xs text-ink-400 mb-2">Separated by commas (e.g., Fiction, Self-Help, Science)</p>
                            <input
                                type="text"
                                className="w-full px-5 py-3 input-libra rounded-2xl outline-none transition"
                                value={settingsData.featuredCategories}
                                onChange={(e) => setSettingsData({ ...settingsData, featuredCategories: e.target.value })}
                                placeholder="Fiction, Self-Help, Science"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-ink-600 mb-2 uppercase tracking-wide">Homepage Banner Text</label>
                            <textarea
                                className="w-full px-5 py-4 input-libra rounded-2xl outline-none transition h-32 resize-none"
                                value={settingsData.homepageBannerText}
                                onChange={(e) => setSettingsData({ ...settingsData, homepageBannerText: e.target.value })}
                                placeholder="Welcome to the ultimate book sanctuary..."
                            />
                        </div>
                        <button
                            type="submit"
                            disabled={updateSettingsMutation.isPending}
                            className="btn-primary w-full py-4 rounded-2xl font-bold"
                        >
                            {updateSettingsMutation.isPending ? 'Saving Configuration...' : 'Save Changes'}
                        </button>
                    </form>
                </div>
            )}
        </div>
    );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getBookDetails } from '../services/googleBooksService';
import api from '../services/api';
import { useAuthStore } from '../store/authStore';
import {
    Loader2, Heart, BookOpen, Clock, CheckCircle, Star, Send, Trash2, ChevronLeft, Calendar, Book, ChevronDown
} from 'lucide-react';
import toast from 'react-hot-toast';
import { getBookReviews, addReview, deleteReview } from '../services/reviewService';
import { favoriteBook, unfavoriteBook, getFavoriteBooks } from '../services/bookService';
import { getMyLists, addToList } from '../services/listService';
import { logActivity } from '../services/activityService';
import ReviewList from '../components/ReviewList';
import ReadingProgressModal from '../components/ReadingProgressModal';
import { updateProgress, getProgress } from '../services/progressService';

const BookDetailsPage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { user } = useAuthStore();
    const queryClient = useQueryClient();
    const [isListOpen, setIsListOpen] = useState(false);

    const { data: book, isLoading, isError } = useQuery({
        queryKey: ['book', id],
        queryFn: () => getBookDetails(id),
    });

    // Fetch existing progress
    const { data: progressData } = useQuery({
        queryKey: ['progress', id],
        queryFn: () => getProgress(id),
        enabled: !!user && !!id
    });

    useEffect(() => {
        if (book && user) {
            logActivity({
                actionType: 'VIEW',
                googleBookId: id,
                bookTitle: book.volumeInfo.title,
                bookAuthor: book.volumeInfo.authors?.[0],
                bookCover: book.volumeInfo.imageLinks?.thumbnail,
                subjects: book.volumeInfo.categories
            });
        }
    }, [book, id, user]);

    const [reviewSort, setReviewSort] = useState('newest');
    const [reviewText, setReviewText] = useState('');
    const [rating, setRating] = useState(0);
    const [isProgressModalOpen, setIsProgressModalOpen] = useState(false);

    const { data: reviewsData, refetch: refetchReviews } = useQuery({
        queryKey: ['reviews', id, reviewSort],
        queryFn: () => getBookReviews(id, reviewSort),
    });

    const { data: favoriteBooks } = useQuery({
        queryKey: ['favoriteBooks'],
        queryFn: getFavoriteBooks,
        enabled: !!user
    });

    const { data: myLists } = useQuery({
        queryKey: ['myLists'],
        queryFn: getMyLists,
        enabled: !!user,
    });

    const isBookFavorited = favoriteBooks?.some(b => b.googleBookId === id);
    const savedStatus = myLists?.find(b => b.googleBookId === id)?.status;

    const toggleFavoriteMutation = useMutation({
        mutationFn: async () => {
            if (isBookFavorited) {
                return await unfavoriteBook(id);
            } else {
                return await favoriteBook({
                    googleBookId: book.id,
                    title: book.volumeInfo.title,
                    authors: book.volumeInfo.authors,
                    thumbnail: book.volumeInfo.imageLinks?.thumbnail,
                    categories: book.volumeInfo.categories,
                    rating: book.volumeInfo.averageRating
                });
            }
        },
        onMutate: async () => {
            // Cancel any outgoing refetches
            await queryClient.cancelQueries({ queryKey: ['favoriteBooks'] });

            // Snapshot the previous value
            const previousFavorites = queryClient.getQueryData(['favoriteBooks']);

            // Optimistically update to the new value
            queryClient.setQueryData(['favoriteBooks'], (old) => {
                if (isBookFavorited) {
                    return old?.filter(b => b.googleBookId !== id);
                } else {
                    return [...(old || []), {
                        googleBookId: id,
                        title: book.volumeInfo.title,
                        thumbnail: book.volumeInfo.imageLinks?.thumbnail,
                        authors: book.volumeInfo.authors
                    }];
                }
            });

            return { previousFavorites };
        },
        onSuccess: () => {
            const status = isBookFavorited ? 'Removed from favorites' : 'Added to favorites';
            toast.success(status);

            if (!isBookFavorited) {
                logActivity({
                    actionType: 'SAVE',
                    googleBookId: id,
                    bookTitle: book?.volumeInfo?.title,
                    bookAuthor: book?.volumeInfo?.authors?.[0],
                    bookCover: book?.volumeInfo?.imageLinks?.thumbnail,
                    keyword: book?.volumeInfo?.title,
                    subjects: book?.volumeInfo?.categories
                });
            }
        },
        onError: (err, variables, context) => {
            toast.error(err.response?.data?.message || 'Failed to update favorites');
            if (context?.previousFavorites) {
                queryClient.setQueryData(['favoriteBooks'], context.previousFavorites);
            }
        },
        onSettled: () => {
            queryClient.invalidateQueries({ queryKey: ['favoriteBooks'] });
        }
    });

    const updateListMutation = useMutation({
        mutationFn: async (newStatus) => {
            await addToList({
                googleBookId: id,
                status: newStatus
            });
        },
        onMutate: async (newStatus) => {
            // Cancel any outgoing refetches
            await queryClient.cancelQueries({ queryKey: ['myLists'] });

            // Snapshot the previous value
            const previousLists = queryClient.getQueryData(['myLists']);

            // Optimistically update to the new value
            queryClient.setQueryData(['myLists'], (old) => {
                const existing = old?.find(b => b.googleBookId === id);
                if (existing) {
                    return old.map(b => b.googleBookId === id ? { ...b, status: newStatus } : b);
                } else {
                    return [...(old || []), { googleBookId: id, status: newStatus }];
                }
            });

            return { previousLists };
        },
        onSuccess: (_, newStatus) => {
            toast.success(`Moved to ${newStatus.replace('_', ' ')}`);

            // Log activity
            logActivity({
                actionType: newStatus === 'COMPLETED' ? 'COMPLETE' : 'STATUS_CHANGE',
                googleBookId: id,
                bookTitle: book?.volumeInfo?.title,
                bookAuthor: book?.volumeInfo?.authors?.[0],
                bookCover: book?.volumeInfo?.imageLinks?.thumbnail,
                keyword: book?.volumeInfo?.title,
                subjects: book?.volumeInfo?.categories
            });
        },
        onError: (err, variables, context) => {
            toast.error(err.response?.data?.message || 'Failed to update shelf');
            if (context?.previousLists) {
                queryClient.setQueryData(['myLists'], context.previousLists);
            }
        },
        onSettled: () => {
            queryClient.invalidateQueries({ queryKey: ['myLists'] });
            queryClient.invalidateQueries({ queryKey: ['favoriteBooks'] });
        }
    });

    const addReviewMutation = useMutation({
        mutationFn: addReview,
        onSuccess: () => {
            toast.success('Review posted');
            setReviewText('');
            refetchReviews();
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Failed to post review');
        }
    });

    const deleteReviewMutation = useMutation({
        mutationFn: deleteReview,
        onSuccess: () => {
            toast.success('Review deleted');
            refetchReviews();
        }
    });

    const handleShelve = (shelf) => {
        updateListMutation.mutate(shelf);
        setIsListOpen(false);
    };

    const handleProgressUpdate = async (page, totalPages) => {
        try {
            await updateProgress({
                googleBookId: id,
                currentPage: page,
                totalPages: totalPages
            });
            toast.success('Progress updated!');
            queryClient.invalidateQueries({ queryKey: ['progress', id] });
            queryClient.invalidateQueries({ queryKey: ['book', id] });
            queryClient.invalidateQueries({ queryKey: ['favoriteBooks'] }); // Invalidate favoriteBooks to reflect status change
        } catch (error) {
            toast.error(error.response?.data?.message || 'Failed to update progress');
        }
    };

    if (isLoading) return <div className="flex justify-center items-center h-screen"><Loader2 className="animate-spin text-teal-600 w-10 h-10" /></div>;
    if (isError || !book) return <div className="text-center py-40 text-ink-400 dark:text-stone-500 font-serif">Book details not found.</div>;

    const volumeInfo = book.volumeInfo;
    const thumbnail = volumeInfo.imageLinks?.thumbnail?.replace('http:', 'https:') || 'https://via.placeholder.com/300x450?text=No+Cover';

    return (
        <div className="min-h-screen bg-paper-50 dark:bg-stone-950 pb-20">
            <div className="max-w-6xl mx-auto px-6 pt-8">
                {/* Back Link */}
                <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-ink-500 dark:text-stone-500 hover:text-ink-900 dark:hover:text-stone-200 mb-6 transition-colors group text-sm font-bold uppercase tracking-wider">
                    <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> Back
                </button>

                <div className="grid md:grid-cols-12 gap-10">
                    {/* LEFT: Cover & Actions */}
                    <div className="md:col-span-4 lg:col-span-3 space-y-6">
                        <div className="relative rounded md:rounded shadow-lg border border-paper-200 dark:border-stone-800 overflow-hidden bg-paper-100 dark:bg-stone-800">
                            <img
                                src={thumbnail.replace('zoom=1', 'zoom=3')}
                                alt={volumeInfo.title}
                                className="w-full h-auto object-cover"
                                onError={(e) => {
                                    e.target.onerror = null;
                                    e.target.src = 'https://via.placeholder.com/300x450?text=No+Cover';
                                }}
                            />
                        </div>

                        {user ? (
                            <>
                                {/* Action Buttons */}
                                <div className="relative">
                                    <button
                                        onClick={() => setIsListOpen(!isListOpen)}
                                        className="w-full py-2 btn-primary flex items-center justify-center gap-2 text-sm font-bold shadow-sm"
                                    >
                                        <span className="flex-1 text-center pl-6">
                                            {savedStatus === 'TO_READ' && 'Want to Read'}
                                            {savedStatus === 'READING' && 'Currently Reading'}
                                            {savedStatus === 'COMPLETED' && 'Read'}
                                            {!savedStatus && 'Add to List'}
                                        </span>
                                        <div className="w-px h-6 bg-white/20"></div>
                                        <ChevronDown size={16} className={`transition-transform px-2 box-content ${isListOpen ? 'rotate-180' : ''}`} />
                                    </button>

                                    {isListOpen && (
                                        <>
                                            <div className="fixed inset-0 z-40" onClick={() => setIsListOpen(false)} />
                                            <div className="absolute top-full left-0 w-full mt-1 bg-paper-50 border border-paper-200 shadow-xl rounded-md overflow-hidden z-50 dark:bg-stone-900 dark:border-stone-800">
                                                <button onClick={() => handleShelve('TO_READ')} className="w-full text-left px-4 py-2 hover:bg-paper-100 text-sm text-ink-900 flex items-center gap-2 dark:hover:bg-stone-800 dark:text-stone-300">
                                                    <Clock size={14} className="text-teal-600" /> Want to Read
                                                </button>
                                                <button onClick={() => handleShelve('READING')} className="w-full text-left px-4 py-2 hover:bg-paper-100 text-sm text-ink-900 flex items-center gap-2 dark:hover:bg-stone-800 dark:text-stone-300">
                                                    <BookOpen size={14} className="text-amber-500" /> Currently Reading
                                                </button>
                                                <button onClick={() => handleShelve('COMPLETED')} className="w-full text-left px-4 py-2 hover:bg-paper-100 text-sm text-ink-900 flex items-center gap-2 dark:hover:bg-stone-800 dark:text-stone-300">
                                                    <CheckCircle size={14} className="text-green-600" /> Read
                                                </button>
                                            </div>
                                        </>
                                    )}
                                </div>

                                {savedStatus === 'READING' && (
                                    <button
                                        onClick={() => setIsProgressModalOpen(true)}
                                        className="w-full py-2 border border-teal-600 text-teal-700 bg-paper-50 font-bold text-sm hover:bg-teal-50 transition-colors rounded dark:bg-stone-900 dark:text-teal-500 dark:hover:bg-stone-800"
                                    >
                                        Update Progress
                                    </button>
                                )}

                                {/* Read Free Button */}
                                {(book.isFree || book.accessInfo?.embeddable || book.accessInfo?.webReaderLink) && (
                                    <button
                                        onClick={() => {
                                            if (book.isFree && book.source === 'gutenberg') {
                                                navigate(`/read/${id}`, { state: { bookData: book } });
                                            } else if (book.accessInfo?.embeddable) {
                                                navigate(`/read/${id}`, { state: { bookData: book } });
                                            } else if (book.accessInfo?.webReaderLink) {
                                                window.open(book.accessInfo.webReaderLink, '_blank');
                                            }
                                        }}
                                        className="w-full py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-sm transition-colors rounded shadow-sm flex items-center justify-center gap-2"
                                    >
                                        <BookOpen size={16} /> Look Inside / Read
                                    </button>
                                )}

                                <div className="flex gap-2">
                                    <button
                                        onClick={() => toggleFavoriteMutation.mutate()}
                                        className={`flex-1 py-1.5 rounded border text-xs font-bold transition-all ${isBookFavorited ? 'bg-red-50 border-red-200 text-red-600 dark:bg-red-900/20 dark:border-red-900/30' : 'bg-paper-50 border-paper-200 text-ink-600 hover:bg-paper-100 dark:bg-stone-900 dark:border-stone-800 dark:text-stone-400 dark:hover:bg-stone-800'}`}
                                    >
                                        {isBookFavorited ? 'Favorited' : 'Favorite'}
                                    </button>
                                </div>
                            </div>
                    </>
                    ) : (
                    <Link to="/login" className="block w-full text-center py-2 btn-primary font-bold text-sm">
                        Sign in to Shelve
                    </Link>
                        )}
                </div>
            </div>

            {/* RIGHT: Metadata & Content */}
            <div className="md:col-span-8 lg:col-span-9 space-y-8">
                <div>
                    <h1 className="text-3xl md:text-4xl font-serif font-bold text-ink-900 dark:text-stone-100 leading-tight mb-2">{volumeInfo.title}</h1>
                    <p className="text-xl text-ink-600 dark:text-stone-400 font-serif">
                        by <span className="text-ink-900 dark:text-stone-200 font-bold hover:underline cursor-pointer">{volumeInfo.authors?.join(', ')}</span>
                    </p>
                </div>

                {/* Description */}
                <div className="prose prose-stone dark:prose-invert prose-sm max-w-none text-ink-800 dark:text-stone-300 leading-relaxed font-sans">
                    <div dangerouslySetInnerHTML={{ __html: volumeInfo.description || '<p>No description available.</p>' }} />
                </div>

                {/* Metadata Grid */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-6 py-6 border-y border-paper-200 dark:border-stone-800">
                    <div>
                        <p className="text-xs text-ink-500 dark:text-stone-500 uppercase font-bold tracking-wider">Pages</p>
                        <p className="text-ink-900 dark:text-stone-200 font-medium">{volumeInfo.pageCount || 'Unknown'}</p>
                    </div>
                    <div>
                        <p className="text-xs text-ink-500 dark:text-stone-500 uppercase font-bold tracking-wider">Format</p>
                        <p className="text-ink-900 dark:text-stone-200 font-medium">Digital / Print</p>
                    </div>
                    <div>
                        <p className="text-xs text-ink-500 dark:text-stone-500 uppercase font-bold tracking-wider">Published</p>
                        <p className="text-ink-900 dark:text-stone-200 font-medium">{volumeInfo.publishedDate?.substring(0, 4)}</p>
                    </div>
                    <div>
                        <p className="text-xs text-ink-500 dark:text-stone-500 uppercase font-bold tracking-wider">ISBN</p>
                        <p className="text-ink-900 dark:text-stone-200 font-medium whitespace-nowrap overflow-hidden text-ellipsis">{volumeInfo.industryIdentifiers?.[0]?.identifier || 'N/A'}</p>
                    </div>
                </div>

                {/* Genres */}
                <div className="flex flex-wrap gap-2">
                    {volumeInfo.categories?.map(cat => (
                        <Link key={cat} to={`/explore?category=${cat}`} className="text-xs font-bold text-teal-700 hover:underline bg-teal-50 dark:bg-teal-900/20 dark:text-teal-500 px-2 py-1 rounded">
                            {cat}
                        </Link>
                    ))}
                </div>

                {/* Reviews Section */}
                <div className="pt-8">
                    <ReviewList
                        reviews={reviewsData?.reviews || []}
                        user={user}
                        onAddReview={({ rating, reviewText }) => addReviewMutation.mutate({ googleBookId: id, rating, reviewText })}
                        onDeleteReview={(reviewId) => deleteReviewMutation.mutate(reviewId)}
                    />
                </div>
            </div>
        </div>

        {/* Modals */ }
    <ReadingProgressModal
        isOpen={isProgressModalOpen}
        onClose={() => setIsProgressModalOpen(false)}
        book={{
            googleBookId: id,
            title: volumeInfo.title,
            authors: volumeInfo.authors,
            coverImage: thumbnail,
            pageCount: volumeInfo.pageCount,
            currentPage: progressData?.currentPage || 0
        }}
        onUpdate={handleProgressUpdate}
    />
    </div >
    );
};

export default BookDetailsPage;

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Trophy, Target, Calendar, BookOpen, Edit2, CheckCircle, TrendingUp } from 'lucide-react';
import { useAuthStore } from '../store/authStore';
import { Link } from 'react-router-dom';
import BookCard from '../components/BookCard';
import ChallengeBookCard from '../components/ChallengeBookCard';
import { getMyLists } from '../services/listService';
import { getPublicProfile } from '../services/statsService';
import toast from 'react-hot-toast';

const ChallengesPage = () => {
    const { user } = useAuthStore();
    const queryClient = useQueryClient();
    const [goal, setGoal] = useState(30); // Default, ideally fetched from user preferences
    const [isEditing, setIsEditing] = useState(false);

    const { data: myLists, isLoading: listLoading } = useQuery({
        queryKey: ['myLists'],
        queryFn: getMyLists,
        enabled: !!user
    });

    const { data: profile, isLoading: profileLoading } = useQuery({
        queryKey: ['myProfile', user?.username],
        queryFn: () => getPublicProfile(user?.username),
        enabled: !!user?.username,
    });

    // Filter books read in 2026
    const currentYear = new Date().getFullYear();
    const readBooks = myLists?.filter(b =>
        b.status === 'COMPLETED' &&
        new Date(b.completedAt || b.updatedAt).getFullYear() === currentYear
    ) || [];
    const progress = readBooks.length;
    const percentage = Math.min(Math.round((progress / goal) * 100), 100);

    // Status message
    const getStatusMessage = () => {
        if (percentage >= 100) return "Incredible! You've crushed your goal!";
        if (percentage >= 50) return "Halfway there! Keep up the momentum.";
        if (percentage >= 10) return "Great start! You're on your way.";
        return "Start your journey today!";
    };

    const handleUpdateGoal = (e) => {
        e.preventDefault();
        setIsEditing(false);
        toast.success(`Goal updated to ${goal} books!`);
        // Here we would call an API to save the user's goal
    };

    return (
        <div className="max-w-7xl mx-auto px-6 py-8 animate-in fade-in duration-500">
            {/* Header */}
            <div className="mb-10 text-center max-w-2xl mx-auto">
                <div className="inline-flex items-center gap-2 bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-500 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-widest mb-4">
                    <Trophy size={14} /> 2026 Reading Challenge
                </div>
                <h1 className="text-4xl md:text-5xl font-serif font-bold text-ink-900 dark:text-stone-100 mb-4">
                    Your Reading Journey
                </h1>
                <p className="text-ink-500 text-lg font-serif">
                    Challenge yourself to read more this year. Track your progress and celebrate every page turned.
                </p>
            </div>

            {/* Main Stats Card */}
            <div className="card-libra p-8 mb-12 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-teal-50/50 dark:bg-teal-900/10 rounded-full -translate-y-1/2 translate-x-1/2 pointer-events-none" />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-12 items-center relative z-10">
                    <div>
                        <div className="flex items-center justify-between mb-2">
                            <h2 className="text-xl font-bold text-ink-900 dark:text-stone-100 flex items-center gap-2">
                                <Target className="text-teal-600" />
                                2026 Goal
                            </h2>
                            {!isEditing ? (
                                <button onClick={() => setIsEditing(true)} className="text-xs font-bold text-ink-400 hover:text-teal-600 flex items-center gap-1">
                                    <Edit2 size={12} /> Edit Goal
                                </button>
                            ) : (
                                <form onSubmit={handleUpdateGoal} className="flex items-center gap-2">
                                    <input
                                        type="number"
                                        value={goal}
                                        onChange={(e) => setGoal(Number(e.target.value))}
                                        className="w-16 input-libra py-0.5 px-2 text-sm"
                                        min="1"
                                    />
                                    <button type="submit" className="text-xs font-bold text-teal-600">Save</button>
                                </form>
                            )}
                        </div>

                        <div className="text-6xl font-serif font-bold text-ink-900 dark:text-stone-100 mb-2">
                            {progress} <span className="text-2xl text-ink-400 dark:text-stone-500 font-sans font-normal">/ {goal}</span>
                        </div>
                        <p className="text-ink-600 font-medium mb-6">{getStatusMessage()}</p>

                        <div className="h-4 bg-paper-200 rounded-full overflow-hidden shadow-inner">
                            <div
                                className="h-full bg-gradient-to-r from-teal-500 to-teal-400 transition-all duration-1000 ease-out relative"
                                style={{ width: `${percentage}%` }}
                            >
                                <div className="absolute inset-0 bg-white/20 animate-pulse" />
                            </div>
                        </div>
                        <div className="flex justify-between mt-2 text-xs font-bold text-ink-400 uppercase tracking-wider">
                            <span>0%</span>
                            <span>{percentage}% Complete</span>
                            <span>100%</span>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                        <div className="bg-paper-50 dark:bg-stone-900/50 p-6 rounded-xl border border-paper-100 dark:border-stone-800 text-center">
                            <BookOpen size={24} className="mx-auto text-amber-500 mb-2" />
                            <div className="text-2xl font-bold text-ink-900 dark:text-stone-100">
                                {profile?.totalPagesRead > 1000 ? `${(profile.totalPagesRead / 1000).toFixed(1)}k` : profile?.totalPagesRead || 0}
                            </div>
                            <div className="text-xs text-ink-400 dark:text-stone-500 font-bold uppercase tracking-wider">Pages Read</div>
                        </div>
                        <div className="bg-paper-50 dark:bg-stone-900/50 p-6 rounded-xl border border-paper-100 dark:border-stone-800 text-center">
                            <TrendingUp size={24} className="mx-auto text-green-500 mb-2" />
                            <div className="text-2xl font-bold text-ink-900 dark:text-stone-100">{profile?.avgPagesPerDay || 0}</div>
                            <div className="text-xs text-ink-400 dark:text-stone-500 font-bold uppercase tracking-wider">Avg Pages/Day</div>
                        </div>
                        <div className="bg-paper-50 dark:bg-stone-900/50 p-6 rounded-xl border border-paper-100 dark:border-stone-800 text-center">
                            <Calendar size={24} className="mx-auto text-purple-500 mb-2" />
                            <div className="text-2xl font-bold text-ink-900 dark:text-stone-100">{profile?.currentStreak || 0}</div>
                            <div className="text-xs text-ink-400 dark:text-stone-500 font-bold uppercase tracking-wider">Current Streak</div>
                        </div>
                        <div className="bg-paper-50 dark:bg-stone-900/50 p-6 rounded-xl border border-paper-100 dark:border-stone-800 text-center">
                            <CheckCircle size={24} className="mx-auto text-blue-500 mb-2" />
                            <div className="text-2xl font-bold text-ink-900 dark:text-stone-100">
                                {profile?.aheadOfSchedule > 0 ? `+${profile.aheadOfSchedule}` : profile?.aheadOfSchedule || 0}
                            </div>
                            <div className="text-xs text-ink-400 dark:text-stone-500 font-bold uppercase tracking-wider">
                                {profile?.aheadOfSchedule >= 0 ? 'Ahead of Sched' : 'Behind Sched'}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Books List */}
            <div>
                <h3 className="text-2xl font-bold font-serif text-ink-900 dark:text-stone-100 mb-6 flex items-center gap-3">
                    Books Read in 2026
                    <span className="text-sm font-sans font-normal text-ink-500 dark:text-stone-400 bg-paper-200 dark:bg-stone-800 px-2 py-0.5 rounded-full">{readBooks.length}</span>
                </h3>

                {listLoading ? (
                    <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-6 animate-pulse">
                        {[...Array(5)].map((_, i) => (
                            <div key={i} className="space-y-2">
                                <div className="aspect-[2/3] bg-paper-200 rounded"></div>
                                <div className="h-3 bg-paper-200 rounded w-3/4"></div>
                            </div>
                        ))}
                    </div>
                ) : readBooks.length > 0 ? (
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-x-6 gap-y-10">
                        {readBooks.map(book => (
                            <ChallengeBookCard key={book.googleBookId} googleBookId={book.googleBookId} />
                        ))}
                    </div>
                ) : (
                    <div className="text-center py-20 bg-paper-50 dark:bg-stone-900/50 rounded-xl border border-dashed border-paper-200 dark:border-stone-800">
                        <BookOpen size={48} className="mx-auto text-ink-300 dark:text-stone-700 mb-4" />
                        <h3 className="text-lg font-bold text-ink-600 dark:text-stone-400 mb-2">No books completed yet</h3>
                        <p className="text-ink-400 dark:text-stone-500 mb-6">Mark a book as "Read" to see it appear here.</p>
                        <Link to="/explore" className="btn-primary px-6 py-2">Find Your First Read</Link>
                    </div>
                )}
            </div>
        </div>
    );
};

export default ChallengesPage;

import React, { useRef } from 'react';
import { useQuery } from '@tanstack/react-query';
import api from '../services/api';
import { useAuthStore } from '../store/authStore';
import { Link } from 'react-router-dom';
import { BookOpen, Heart, Clock, CheckCircle, Loader2, Sparkles, ChevronRight, Star } from 'lucide-react';
import ListBookCard from '../components/ListBookCard';

const DashboardPage = () => {
    const { user } = useAuthStore();
    const readingRef = useRef(null);
    const toReadRef = useRef(null);
    const completedRef = useRef(null);

    const { data: favoriteBooks, isLoading: favoriteLoading } = useQuery({
        queryKey: ['favoriteBooks'],
        queryFn: async () => {
            const res = await api.get('/books/favorites');
            return res.data;
        }
    });

    const { data: myLists, isLoading: lisLoading } = useQuery({
        queryKey: ['myLists'],
        queryFn: async () => {
            const res = await api.get('/lists/my');
            return res.data;
        }
    });

    const readingItems = myLists?.filter(l => l.status === 'READING') || [];
    const toReadItems = myLists?.filter(l => l.status === 'TO_READ') || [];
    const completedItems = myLists?.filter(l => l.status === 'COMPLETED') || [];

    const { data: myRecsData } = useQuery({
        queryKey: ['myRecommendations'],
        queryFn: async () => {
            const res = await api.get('/recommendations/my');
            return res.data;
        },
        enabled: !!user,
    });

    const recommendations = myRecsData?.feed || [];

    const { data: globalRecs } = useQuery({
        queryKey: ['globalRecommendations'],
        queryFn: async () => {
            const res = await api.get('/recommendations/global');
            return res.data;
        }
    });

    const scrollTo = (ref) => {
        ref.current?.scrollIntoView({ behavior: 'smooth' });
    };

    if (favoriteLoading || lisLoading) return (
        <div className="flex justify-center py-20">
            <Loader2 className="animate-spin text-gray-400 w-10 h-10" />
        </div>
    );

    return (
        <div className="max-w-4xl mx-auto space-y-20 pb-24 px-4 overflow-hidden">
            {/* Simple Greeting */}
            <header className="space-y-4 pt-12 transition-colors duration-300">
                <h1 className="text-4xl lg:text-5xl font-bold text-ink-900 dark:text-stone-100 serif">Hello, {user?.name.split(' ')[0]}</h1>
                <p className="text-lg text-ink-600 dark:text-stone-400 font-medium italic">Your personal reading journal at a glance.</p>
                <div className="flex flex-wrap gap-4 pt-4">
                    <button onClick={() => scrollTo(readingRef)} className="flex items-center space-x-2 text-sm font-bold text-teal-600 bg-teal-50 px-4 py-2 rounded-full border border-teal-100 hover:bg-teal-100 transition-colors dark:bg-teal-900/20 dark:border-teal-900/30 dark:text-teal-400 dark:hover:bg-teal-900/40">
                        <BookOpen size={16} /> <span>Reading ({readingItems.length})</span>
                    </button>
                    <button onClick={() => scrollTo(toReadRef)} className="flex items-center space-x-2 text-sm font-bold text-ink-600 bg-paper-100 px-4 py-2 rounded-full border border-paper-200 hover:bg-paper-200 transition-colors dark:bg-stone-800 dark:border-stone-700 dark:text-stone-400 dark:hover:bg-stone-700">
                        <Clock size={16} /> <span>To Read ({toReadItems.length})</span>
                    </button>
                    <button onClick={() => scrollTo(completedRef)} className="flex items-center space-x-2 text-sm font-bold text-blue-600 bg-blue-50 px-4 py-2 rounded-full border border-blue-100 hover:bg-blue-100 transition-colors dark:bg-blue-900/20 dark:border-blue-900/30 dark:text-blue-400 dark:hover:bg-blue-900/40">
                        <CheckCircle size={16} /> <span>Completed ({completedItems.length})</span>
                    </button>
                </div>
            </header>

            {/* Combined Recommendations Feed */}
            {recommendations.length > 0 && recommendations.map((section, idx) => (
                <section key={idx} className="space-y-6">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-3">
                            {section.type === 'GLOBAL' ? (
                                <Star size={24} className="text-purple-500 fill-purple-500/10" />
                            ) : (
                                <Sparkles size={24} className="text-amber-500 fill-amber-500/10" />
                            )}
                            <div>
                                <h2 className="text-2xl font-bold serif text-ink-900 dark:text-stone-100">{section.title}</h2>
                                <p className="text-xs text-ink-400 dark:text-stone-500 font-medium italic">{section.description}</p>
                            </div>
                        </div>
                    </div>
                    <div className="flex gap-6 overflow-x-auto pb-6 scrollbar-hide snap-x -mx-4 px-4">
                        {section.books.map(book => {
                            const isFlat = !!(book.title && (Array.isArray(book.authors) || typeof book.authors === 'string'));
                            const title = isFlat ? book.title : book.volumeInfo?.title;
                            const authors = isFlat ? book.authors : book.volumeInfo?.authors;

                            // High quality thumbnail handling
                            let thumbnail = book.coverImage || book.thumbnail || (isFlat ? null : book.volumeInfo?.imageLinks?.thumbnail);
                            if (thumbnail) {
                                thumbnail = thumbnail.replace('http:', 'https:').replace('zoom=1', 'zoom=2');
                            } else {
                                thumbnail = `https://via.placeholder.com/300x450?text=${encodeURIComponent(title || 'No Cover')}`;
                            }

                            const id = book.googleBookId || book.id || (isFlat ? null : book.id);

                            return (
                                <Link key={id} to={`/book/${id}`} className="min-w-[140px] w-[140px] snap-start group space-y-3">
                                    <div className="aspect-[2/3] rounded-xl overflow-hidden border border-gray-100 dark:border-stone-800 shadow-sm transition-all group-hover:-translate-y-2 group-hover:shadow-xl relative bg-paper-100 dark:bg-stone-800">
                                        <img
                                            src={thumbnail}
                                            alt={title}
                                            className="w-full h-full object-cover"
                                            loading="lazy"
                                            onError={(e) => {
                                                e.target.onerror = null;
                                                const fallbackIdx = (idx + (title?.length || 0)) % 4;
                                                const colors = ['teal', 'indigo', 'amber', 'rose'];
                                                e.target.src = `https://ui-avatars.com/api/?name=${encodeURIComponent(title || 'B')}&background=${colors[fallbackIdx]}&color=fff&size=512&bold=true`;
                                            }}
                                        />
                                        {book.reasons && book.reasons[0] && (
                                            <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/90 via-black/60 to-transparent p-3 pt-6">
                                                <p className="text-[10px] text-white/90 font-bold leading-tight line-clamp-2 uppercase tracking-wider">{book.reasons[0]}</p>
                                            </div>
                                        )}
                                        <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <div className="bg-white/90 backdrop-blur-sm p-1.5 rounded-full shadow-lg">
                                                <ChevronRight size={14} className="text-teal-600" />
                                            </div>
                                        </div>
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-gray-900 dark:text-stone-100 text-[13px] leading-tight line-clamp-2 serif group-hover:text-teal-600 transition-colors">{title}</h3>
                                        <p className="text-[11px] text-gray-400 dark:text-stone-500 mt-1 truncate">{Array.isArray(authors) ? authors[0] : authors}</p>
                                    </div>
                                </Link>
                            );
                        })}
                    </div>
                </section>
            ))}

            {/* Fallback Trending if no specific recs (though we should always have some) */}
            {recommendations.length === 0 && globalRecs && globalRecs.length > 0 && (
                <section className="space-y-6">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-2">
                            <Star size={24} className="text-purple-500" />
                            <h2 className="text-2xl font-bold serif text-ink-900 dark:text-stone-100">Popular on Bookverse</h2>
                        </div>
                    </div>
                    <div className="flex gap-6 overflow-x-auto pb-6 scrollbar-hide snap-x">
                        {globalRecs.map(book => (
                            <Link key={book.googleBookId} to={`/book/${book.googleBookId}`} className="min-w-[140px] w-[140px] snap-start group space-y-2">
                                <div className="aspect-[2/3] rounded-lg overflow-hidden border border-gray-100 dark:border-stone-800 shadow-sm transition-transform group-hover:-translate-y-1 group-hover:shadow-md bg-paper-100 dark:bg-stone-800">
                                    <img
                                        src={book.coverImage?.replace('zoom=1', 'zoom=2') || 'https://via.placeholder.com/200x300'}
                                        alt={book.title}
                                        className="w-full h-full object-cover"
                                    />
                                </div>
                                <h3 className="font-bold text-gray-900 dark:text-stone-100 text-xs truncate serif">{book.title}</h3>
                                <p className="text-[10px] text-gray-400 dark:text-stone-500 truncate">{book.authors?.[0]}</p>
                            </Link>
                        ))}
                    </div>
                </section>
            )}

            {/* Currently Reading */}
            <section ref={readingRef} className="space-y-10 scroll-mt-32">
                <div className="flex items-center justify-between border-b border-gray-100 dark:border-stone-800 pb-4">
                    <h2 className="text-2xl font-bold serif text-ink-900 dark:text-stone-100">Currently Reading</h2>
                    <Link to="/lists" className="text-sm font-semibold text-gray-400 dark:text-stone-500 hover:text-gray-900 dark:hover:text-stone-300 flex items-center gap-1 transition-colors">
                        Manage all lists <ChevronRight size={16} />
                    </Link>
                </div>
                {readingItems.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        {readingItems.map(item => (
                            <ListBookCard key={item._id} item={item} dark={true} />
                        ))}
                    </div>
                ) : (
                    <div className="py-20 text-center bg-paper-50 dark:bg-stone-900/50 rounded-2xl border border-dashed border-paper-200 dark:border-stone-800">
                        <p className="text-ink-400 dark:text-stone-500 font-medium italic">You're not reading anything at the moment.</p>
                        <Link to="/explore" className="text-teal-600 dark:text-teal-500 font-bold text-sm block mt-4">Browse library</Link>
                    </div>
                )}
            </section>

            {/* To Read List - Simple Grid */}
            <section ref={toReadRef} className="space-y-10 scroll-mt-32">
                <div className="flex items-center justify-between border-b border-gray-100 pb-4">
                    <h2 className="text-2xl font-bold serif">Ready to dive in</h2>
                    <span className="text-sm font-bold text-gray-300 uppercase tracking-widest">{toReadItems.length} Books</span>
                </div>
                {toReadItems.length > 0 ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
                        {toReadItems.map(item => (
                            <ListBookCard key={item._id} item={item} small dark={false} />
                        ))}
                    </div>
                ) : (
                    <div className="py-20 text-center bg-paper-50 border border-dashed border-paper-200 rounded-2xl">
                        <p className="text-ink-400 font-medium italic">Your reading queue is empty.</p>
                    </div>
                )}
            </section>

            {/* Completed Archive */}
            <section ref={completedRef} className="space-y-10 scroll-mt-32">
                <div className="flex items-center justify-between border-b border-gray-100 dark:border-stone-800 pb-4">
                    <h2 className="text-2xl font-bold serif text-ink-900 dark:text-stone-100">Finished</h2>
                    <p className="text-sm font-semibold text-gray-400 dark:text-stone-500 italic">Total of {completedItems.length} books read</p>
                </div>
                {completedItems.length > 0 ? (
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-8">
                        {completedItems.map(item => (
                            <Link key={item._id} to={`/book/${item.googleBookId}`} className="group space-y-3">
                                <div className="aspect-[2/3] rounded-lg overflow-hidden border border-paper-200 dark:border-stone-800 shadow-sm transition-transform group-hover:-translate-y-1 group-hover:shadow-md bg-paper-100 dark:bg-stone-800">
                                    <ShelfItem googleBookId={item.googleBookId} />
                                </div>
                                <div className="text-center">
                                    <p className="text-[10px] font-bold uppercase tracking-widest text-green-600 dark:text-green-500">Completed</p>
                                    <p className="text-xs text-ink-400 dark:text-stone-500 mt-1">{new Date(item.completedAt).toLocaleDateString()}</p>
                                </div>
                            </Link>
                        ))}
                    </div>
                ) : (
                    <div className="py-20 text-center bg-paper-50 dark:bg-stone-900/50 rounded-2xl border border-dashed border-paper-200 dark:border-stone-800">
                        <p className="text-ink-400 dark:text-stone-500 font-medium italic">You haven't added any completed books yet.</p>
                    </div>
                )}
            </section>
        </div>
    );
};

const ShelfItem = ({ googleBookId }) => {
    const { data: bookDetails } = useQuery({
        queryKey: ['book', googleBookId],
        queryFn: () => import('../services/googleBooksService').then(m => m.getBookDetails(googleBookId)),
        staleTime: 1000 * 60 * 60,
    });

    if (!bookDetails) return <div className="w-full h-full bg-gray-50 dark:bg-stone-800 animate-pulse" />;

    const thumbnail = bookDetails.volumeInfo.imageLinks?.thumbnail?.replace('http:', 'https:').replace('zoom=1', 'zoom=2');
    const rating = bookDetails.volumeInfo.averageRating;

    return (
        <div className="relative w-full h-full">
            <img src={thumbnail} alt={bookDetails.volumeInfo.title} className="w-full h-full object-cover" />
            {rating && (
                <div className="absolute bottom-2 right-2 bg-black/60 backdrop-blur-sm text-white text-[8px] font-bold px-1.5 py-0.5 rounded flex items-center gap-1 border border-white/10">
                    <Star size={8} className="text-yellow-400 fill-current" />
                    <span>{rating}</span>
                </div>
            )}
        </div>
    );
};

export default DashboardPage;

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import api from '../services/api';
import BookCard from '../components/BookCard';
import { Sparkles, TrendingUp, BookOpen, Star, ArrowRight } from 'lucide-react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';

import { DISCOVER_FEED } from '../data/discoverData';

const DiscoverPage = () => {
    // We are now loading the Discover page data locally from code to ensure 100% accuracy
    // and bypassing the database as requested by the user.
    const data = {
        feed: DISCOVER_FEED,
        categories: [
            { name: 'FICTION' },
            { name: 'TECHNOLOGY' },
            { name: 'SCIENCE' },
            { name: 'HISTORY' }
        ]
    };

    const { data: freeBooksData, isLoading: isFreeLoading } = useQuery({
        queryKey: ['freeBooks'],
        queryFn: async () => {
            const res = await api.get('/discover/free?topic=fiction&page=1');
            return res.data;
        }
    });

    const isLoading = isFreeLoading;

    if (isLoading) {
        return (
            <div className="min-h-screen bg-paper-50 dark:bg-stone-950 pt-12 text-center">
                <div className="animate-pulse space-y-12 max-w-7xl mx-auto px-6">
                    <div className="h-10 bg-paper-200 dark:bg-stone-800 w-1/4 rounded mx-auto mb-12"></div>
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-4">
                        {[...Array(6)].map((_, i) => (
                            <div key={i} className="h-14 bg-paper-200 rounded-xl"></div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    const { feed: staticFeed, categories, featured } = data || {};

    let combinedFeed = staticFeed ? [...staticFeed] : [];

    // Insert the "Free Books" section at the top
    if (freeBooksData?.results?.length > 0) {
        combinedFeed.unshift({
            title: "Free & Public Domain Classics",
            description: "Timeless masterpieces you can read right now for free.",
            category: "FREE",
            books: freeBooksData.results
        });
    }

    return (
        <div className="min-h-screen bg-paper-50 dark:bg-stone-950 pb-20">
            {/* Immersive Hero with Vibrant Gradient - Truly Compact */}
            <header className="relative pt-8 pb-6 px-6 overflow-hidden bg-gradient-to-br from-teal-900 via-ink-950 to-indigo-950 border-b border-white/5">
                {/* Decorative background effects */}
                <div className="absolute top-0 right-0 w-[300px] h-[300px] bg-teal-500/10 blur-[60px] rounded-full pointer-events-none -translate-y-1/2 translate-x-1/2" />
                <div className="absolute bottom-0 left-0 w-[300px] h-[300px] bg-indigo-500/10 blur-[60px] rounded-full pointer-events-none translate-y-1/2 -translate-x-1/2" />

                <div className="max-w-5xl mx-auto relative z-10">
                    <div className="flex flex-col lg:flex-row items-center gap-10">
                        {/* Text Content */}
                        <div className="flex-1 text-center lg:text-left space-y-3">
                            <motion.div
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                className="inline-flex items-center gap-2 px-3 py-1 bg-white/5 border border-white/10 rounded-full text-teal-400 text-[9px] font-black uppercase tracking-[0.25em] backdrop-blur-md"
                            >
                                <Sparkles size={10} className="animate-pulse" />
                                Discovery
                            </motion.div>
                            <motion.h1
                                initial={{ opacity: 0, y: 15 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: 0.1 }}
                                className="text-3xl md:text-4xl font-serif font-black text-white tracking-tighter leading-[1.1]"
                            >
                                Explore the <br />
                                <span className="text-transparent bg-clip-text bg-gradient-to-r from-teal-400 to-emerald-300 italic pr-2 text-4xl md:text-5xl">Bookverse</span>
                            </motion.h1>
                            <motion.p
                                initial={{ opacity: 0, y: 15 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: 0.2 }}
                                className="text-sm md:text-base text-ink-300/80 font-serif max-w-sm leading-relaxed"
                            >
                                Find your next favorite masterpiece from 200+ curated titles.
                            </motion.p>
                        </div>

                        {/* Featured Spotlight Card - Ultra Compact */}
                        {featured && (
                            <motion.div
                                initial={{ opacity: 0, scale: 0.9, x: 20 }}
                                animate={{ opacity: 1, scale: 1, x: 0 }}
                                transition={{ type: "spring", damping: 25, delay: 0.3 }}
                                className="flex-shrink-0 w-full max-w-xs"
                            >
                                <Link to={`/book/${featured.googleBookId}`} className="block group">
                                    <div className="bg-white/[0.04] backdrop-blur-3xl border border-white/10 p-4 rounded-xl flex items-center gap-4 hover:bg-white/[0.08] transition-all duration-500 shadow-2xl group-hover:border-teal-500/30">
                                        <div className="w-16 md:w-20 aspect-[2/3] rounded overflow-hidden shadow-2xl flex-shrink-0 group-hover:scale-105 transition-transform duration-700">
                                            <img
                                                src={featured.coverImage?.replace('zoom=1', 'zoom=2')}
                                                alt={featured.title}
                                                className="w-full h-full object-cover"
                                                onError={(e) => {
                                                    e.target.src = featured.coverImage?.replace('zoom=2', 'zoom=1');
                                                }}
                                            />
                                        </div>
                                        <div className="flex-1 min-w-0 space-y-2">
                                            <div className="flex items-center gap-2">
                                                <span className="px-2 py-0.5 bg-teal-500/20 text-teal-400 rounded-full text-[9px] font-bold tracking-widest uppercase">Spotlight</span>
                                            </div>
                                            <h2 className="text-lg md:text-xl font-serif font-bold text-white line-clamp-2 leading-tight tracking-tight">{featured.title}</h2>
                                            <p className="text-sm text-ink-300 font-medium opacity-80">{featured.authors?.[0]}</p>
                                            <div className="inline-flex items-center gap-1.5 px-2 py-1 bg-white/5 rounded-lg border border-white/10">
                                                <TrendingUp size={12} className="text-teal-400" />
                                                <span className="text-[10px] text-white font-bold uppercase tracking-wider">Trending Item</span>
                                            </div>
                                        </div>
                                    </div>
                                </Link>
                            </motion.div>
                        )}
                    </div>
                </div>
            </header>

            {/* Hub Sections */}
            <div className="max-w-[1400px] mx-auto px-6 py-8 space-y-16">

                {/* Categories Pill Navigation */}
                <section>
                    <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-2">
                            <BookOpen size={18} className="text-teal-600" />
                            <h2 className="text-xl font-serif font-bold text-ink-900 dark:text-stone-100">Browse by Interest</h2>
                        </div>
                    </div>
                    <div className="flex flex-wrap gap-3">
                        {categories?.map((cat, idx) => (
                            <Link
                                to={`/explore?q=${cat.name}`}
                                key={idx}
                                className="px-4 py-2 rounded-full bg-white border border-paper-200 hover:border-teal-500 hover:bg-teal-50 text-ink-600 hover:text-teal-700 transition-all font-bold text-[10px] uppercase tracking-widest dark:bg-stone-900 dark:border-stone-800 dark:text-stone-400"
                            >
                                {cat.name}
                            </Link>
                        ))}
                    </div>
                </section>

                {/* Feed Sections */}
                {combinedFeed?.map((section, idx) => (
                    <motion.section
                        key={idx}
                        initial={{ opacity: 0, y: 30 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ delay: idx * 0.1 }}
                    >
                        <div className="flex items-end justify-between mb-6 pb-3 border-b border-paper-100 dark:border-stone-800">
                            <div>
                                <h2 className="text-2xl font-serif font-bold text-ink-900 dark:text-stone-100 tracking-tight">
                                    {section.title}
                                </h2>
                                <p className="text-ink-500 dark:text-stone-400 text-xs font-medium mt-0.5">{section.description}</p>
                            </div>
                            <Link to={`/explore?q=${section.title.includes('Titan') ? 'Technology' : ''}`} className="text-sm font-bold text-teal-600 hover:text-teal-800 flex items-center gap-1 transition-colors group">
                                View Full Collection <ArrowRight size={16} className="group-hover:translate-x-1 transition-transform" />
                            </Link>
                        </div>

                        <div className="relative">
                            <div className="flex gap-6 overflow-x-auto pb-10 -mx-6 px-6 scrollbar-hide snap-x">
                                {section.books.map((book) => (
                                    <div key={book.googleBookId || book.openLibraryId || book._id} className="snap-start shrink-0 w-[200px] md:w-[240px]">
                                        <BookCard book={book} className="w-full" />
                                    </div>
                                ))}
                            </div>
                            {/* Desktop Fade */}
                            <div className="absolute top-0 right-0 bottom-10 w-32 bg-gradient-to-l from-paper-50 to-transparent pointer-events-none hidden lg:block dark:from-stone-900" />
                        </div>
                    </motion.section>
                ))}
            </div>

            {/* Elevated Personalized CTA - Compacted */}
            <section className="mx-6 max-w-5xl lg:mx-auto bg-gradient-to-br from-ink-900 to-stone-900 rounded-[2.5rem] p-8 md:p-12 text-white text-center relative shadow-3xl overflow-hidden mt-8 border border-white/5">
                <div className="relative z-10 max-w-2xl mx-auto space-y-6">
                    <div className="inline-block p-3 bg-teal-500/20 rounded-2xl backdrop-blur-xl">
                        <Sparkles size={32} className="text-teal-400 animate-pulse" />
                    </div>
                    <h2 className="text-3xl md:text-5xl font-serif font-bold leading-tight text-white">Ready for your <span className="italic text-teal-400">Next Chapter</span>?</h2>
                    <p className="text-base text-stone-300 font-serif leading-relaxed max-w-xl mx-auto">
                        Your library is unique. We analyze your reading patterns across 11+ genres to find the books you actually want to read.
                    </p>
                    <Link to="/recommendations" className="inline-flex items-center gap-2 px-8 py-4 bg-teal-600 hover:bg-teal-500 text-white rounded-full font-bold text-lg transition-all shadow-2xl hover:scale-105 active:scale-95">
                        Get Personal Recommendations <ArrowRight size={18} />
                    </Link>
                </div>

                {/* Decorative glow */}
                <div className="absolute top-0 right-0 w-96 h-96 bg-teal-500/10 blur-[150px] rounded-full pointer-events-none" />
                <div className="absolute bottom-0 left-0 w-96 h-96 bg-purple-500/5 blur-[150px] rounded-full pointer-events-none" />
            </section>
        </div>
    );
};

export default DiscoverPage;

