const PublicShelfItem = ({ googleBookId }) => {
    const { data: bookDetails } = useQuery({
        queryKey: ['book', googleBookId],
        queryFn: () => import('../services/googleBooksService').then(m => m.getBookDetails(googleBookId)),
        staleTime: 1000 * 60 * 60,
    });

    if (!bookDetails) return <div className="w-full h-full bg-paper-100 dark:bg-stone-900 animate-pulse" />;

    const thumbnail = bookDetails.volumeInfo.imageLinks?.thumbnail?.replace('http:', 'https:').replace('zoom=1', 'zoom=2');
    return (
        <img
            src={thumbnail || `https://ui-avatars.com/api/?name=${encodeURIComponent(bookDetails.volumeInfo.title || 'B')}&background=0D9488&color=fff&size=512&bold=true`}
            alt={bookDetails.volumeInfo.title}
            className="w-full h-full object-cover"
            onError={(e) => {
                e.target.onerror = null;
                const colors = ['0D9488', '0891B2', '4F46E5', '7C3AED', 'DB2777', '2563EB'];
                const fallbackIdx = Math.abs(googleBookId?.charCodeAt(0) || 0) % colors.length;
                e.target.src = `https://ui-avatars.com/api/?name=${encodeURIComponent(bookDetails.volumeInfo.title || 'B')}&background=${colors[fallbackIdx]}&color=fff&size=512&bold=true`;
            }}
        />
    );
};

export default LandingPage;

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import api from '../services/api';
import { Loader2, BookOpen, Search, Filter } from 'lucide-react';
import ListBookCard from '../components/ListBookCard';

const MyListsPage = () => {
    const [activeTab, setActiveTab] = useState('TO_READ');


    const { data: listItems, isLoading: listLoading } = useQuery({
        queryKey: ['myLists'],
        queryFn: async () => {
            const res = await api.get('/lists/my');
            return res.data;
        }
    });

    const isLoading = listLoading;

    const filteredItems = listItems?.filter(item => item.status === activeTab) || [];

    const tabs = [
        { id: 'READING', label: 'Currently Reading', count: listItems?.filter(i => i.status === 'READING').length },
        { id: 'TO_READ', label: 'Want to Read', count: listItems?.filter(i => i.status === 'TO_READ').length },
        { id: 'COMPLETED', label: 'Read', count: listItems?.filter(i => i.status === 'COMPLETED').length },
    ];

    if (isLoading) return <div className="flex justify-center py-20"><Loader2 className="animate-spin text-teal-600 w-10 h-10" /></div>;

    return (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in duration-500">

            {/* Sidebar Navigation */}
            <aside className="lg:col-span-3 space-y-6">
                <div className="card-libra p-0 overflow-hidden dark:bg-stone-900 dark:border-stone-800">
                    <div className="p-4 border-b border-paper-200 dark:border-stone-800 bg-paper-50 dark:bg-stone-900">
                        <h2 className="font-bold text-ink-900 dark:text-stone-100 font-serif">Bookshelves</h2>
                    </div>
                    <div className="flex flex-col">
                        {tabs.map(tab => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`flex items-center justify-between px-4 py-3 text-sm font-medium border-l-4 transition-colors ${activeTab === tab.id
                                    ? 'border-teal-600 bg-paper-100 text-teal-700 dark:bg-stone-800 dark:text-teal-500'
                                    : 'border-transparent text-ink-600 hover:bg-paper-50 hover:text-ink-900'
                                    }`}
                            >
                                <span>{tab.label}</span>
                                <span className="text-xs bg-paper-200 dark:bg-stone-800 px-2 py-0.5 rounded-full text-ink-600 dark:text-stone-400">{tab.count || 0}</span>
                            </button>
                        ))}
                    </div>
                </div>

                <div className="card-libra p-4 dark:bg-stone-900 dark:border-stone-800">
                    <h3 className="font-bold text-ink-900 dark:text-stone-100 text-sm mb-2">Reading Stats</h3>
                    {(() => {
                        const currentYear = new Date().getFullYear();
                        const completedThisYear = listItems?.filter(i =>
                            i.status === 'COMPLETED' &&
                            // Check updated date or created date? Ideally completed date. 
                            // Assuming `updatedAt` is close enough to completion time for now.
                            new Date(i.updatedAt || Date.now()).getFullYear() === currentYear
                        ).length || 0;
                        const goal = 30; // Hardcoded goal for now, or fetch from user settings later
                        const percentage = Math.min((completedThisYear / goal) * 100, 100);

                        return (
                            <>
                                <div className="h-2 bg-paper-200 dark:bg-stone-800 rounded-full overflow-hidden mb-1">
                                    <div className="bg-teal-600 h-full transition-all duration-500" style={{ width: `${percentage}%` }}></div>
                                </div>
                                <p className="text-xs text-ink-500 dark:text-stone-500">{completedThisYear} of {goal} books read ({currentYear} Challenge)</p>
                            </>
                        );
                    })()}
                </div>
            </aside>

            {/* Main Content */}
            <main className="lg:col-span-9">
                <div className="flex items-center justify-between mb-6">
                    <h1 className="text-2xl font-bold font-serif text-ink-900 dark:text-stone-100">My Books</h1>


                </div>

                {/* Table Header */}
                <div className="bg-paper-100 dark:bg-stone-900 border border-paper-200 dark:border-stone-800 rounded-t-lg px-4 py-2 grid grid-cols-1 md:grid-cols-12 gap-4 text-xs font-bold text-ink-500 dark:text-stone-500 uppercase tracking-wider">
                    <div className="md:col-span-6">Cover / Title</div>
                    <div className="md:col-span-3 hidden md:block">Avg Rating</div>
                    <div className="md:col-span-3 hidden md:block">Date Added</div>
                </div>

                <div className="bg-paper-50 dark:bg-stone-950 border-x border-b border-paper-200 dark:border-stone-800 rounded-b-lg divide-y divide-paper-100 dark:divide-stone-800 min-h-[400px]">
                    {filteredItems.length > 0 ? (
                        filteredItems.map(item => (
                            <div key={item._id} className="px-4">
                                <ListBookCard item={item} showRemove={true} />
                            </div>
                        ))
                    ) : (
                        <div className="flex flex-col items-center justify-center py-20 text-ink-400 dark:text-stone-600">
                            <BookOpen size={48} className="mb-4 opacity-50" />
                            <p className="mb-4">No books on this shelf yet.</p>
                        </div>
                    )}
                </div>
            </main>
        </div>
    );
};

export default MyListsPage;

import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import api from '../services/api';
import { useAuthStore } from '../store/authStore';
import { useQuery } from '@tanstack/react-query';
import { getPublicProfile } from '../services/statsService';
import toast from 'react-hot-toast';
import {
    User, Settings, BarChart2, Activity, Book, ExternalLink, Loader2, Camera, Shield, Award, Star, CheckCircle, Cpu, Zap, Trophy, Flame
} from 'lucide-react';
import { ResponsiveContainer, BarChart, Bar, XAxis, Tooltip, Cell, PieChart, Pie, YAxis } from 'recharts';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';

const schema = z.object({
    name: z.string().min(2, 'Name must be at least 2 characters'),
    username: z.string()
        .min(3, 'Username must be at least 3 characters')
        .regex(/^[a-zA-Z0-9_]+$/, 'Alphanumeric and underscore only'),
    email: z.string().email('Invalid email address'),
    password: z.string().optional().or(z.literal('')),
    avatar: z.string().url('Invalid URL').optional().or(z.literal('')),
});

const ProfilePage = () => {
    const { user, login } = useAuthStore();
    const [activeTab, setActiveTab] = useState('portfolio');

    const { data: profile, isLoading } = useQuery({
        queryKey: ['myProfile', user?.username],
        queryFn: () => getPublicProfile(user?.username),
        enabled: !!user?.username,
    });

    const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm({
        resolver: zodResolver(schema),
        defaultValues: {
            name: user?.name,
            username: user?.username || '',
            email: user?.email,
            avatar: user?.avatar || '',
            password: ''
        }
    });

    const onSubmit = async (data) => {
        try {
            const payload = { ...data };
            if (!payload.password) delete payload.password;

            const response = await api.put('/users/me', payload);
            login(response.data, response.data.token);
            toast.success('Your profile has been updated');
        } catch (error) {
            toast.error(error.response?.data?.message || 'Update failed');
        }
    };

    if (isLoading) return <div className="flex justify-center items-center h-screen"><Loader2 className="animate-spin text-teal-600 w-10 h-10" /></div>;

    // Libra Palette for Charts
    const COLORS = ['#0d9488', '#f59e0b', '#57534e', '#a8a29e', '#f5f5f4'];

    const CustomTooltip = ({ active, payload, label }) => {
        if (active && payload && payload.length) {
            return (
                <div className="bg-paper-50 p-3 border border-paper-200 rounded shadow-lg text-xs dark:bg-stone-800 dark:border-stone-700">
                    <p className="font-bold text-ink-900 mb-1 dark:text-stone-100">{label}</p>
                    <p className="text-teal-700 font-bold dark:text-teal-500">{`${payload[0].value} units`}</p>
                </div>
            );
        }
        return null;
    };

    const genreData = profile?.genreDistribution?.length > 0 ? profile.genreDistribution : [
        { name: 'Fiction', value: 40 },
        { name: 'Science', value: 30 },
        { name: 'History', value: 30 },
    ];

    const weeklyActivity = profile?.weeklyActivity || [];

    return (
        <div className="min-h-screen bg-paper-50 dark:bg-stone-950 pb-20 pt-10">
            <div className="max-w-6xl mx-auto px-6 space-y-8">

                {/* Header Section */}
                <div className="card-libra p-8 md:p-10 flex flex-col md:flex-row items-center md:items-start gap-8">
                    <div className="relative group shrink-0">
                        <div className="w-32 h-32 md:w-36 md:h-36 rounded-full p-1 bg-paper-50 dark:bg-stone-900 border border-paper-300 dark:border-stone-700 shadow-sm">
                            <div className="w-full h-full rounded-full bg-paper-100 dark:bg-stone-800 flex items-center justify-center overflow-hidden">
                                {user?.avatar ?
                                    <img src={user.avatar} className="w-full h-full object-cover" alt="" />
                                    : <User size={64} strokeWidth={1.5} className="text-ink-400 dark:text-stone-500" />
                                }
                            </div>
                        </div>
                    </div>

                    <div className="flex-1 text-center md:text-left space-y-4">
                        <div>
                            <h1 className="text-3xl md:text-4xl font-serif font-bold text-ink-900 dark:text-stone-100 mb-1">{user?.name}</h1>
                            <p className="text-ink-500 dark:text-stone-400 font-medium">@{user?.username || 'reader'}</p>
                        </div>

                        <div className="flex flex-wrap justify-center md:justify-start gap-3">
                            <span className="px-3 py-1 rounded bg-teal-50 border border-teal-100 text-xs font-bold text-teal-700 flex items-center gap-1.5">
                                <Shield size={12} fill="currentColor" /> Verified
                            </span>
                            <Link to={`/users/${user?.username}`} className="px-3 py-1 rounded bg-paper-50 border border-paper-200 text-xs font-bold text-ink-600 hover:bg-paper-100 transition-colors flex items-center gap-1.5 dark:bg-stone-800 dark:border-stone-700 dark:text-stone-400 dark:hover:bg-stone-700">
                                <ExternalLink size={12} /> Public Profile
                            </Link>
                        </div>
                    </div>

                    <div className="flex gap-8 border-l border-paper-200 dark:border-stone-700 pl-8 hidden md:flex">
                        <div className="text-center">
                            <p className="text-3xl font-serif font-bold text-ink-900 dark:text-stone-100">{profile?.totalBooksRead || 0}</p>
                            <p className="text-[10px] font-bold uppercase tracking-widest text-ink-400 dark:text-stone-500 mt-1">Books Read</p>
                        </div>
                        <div className="text-center">
                            <p className="text-3xl font-serif font-bold text-ink-900 dark:text-stone-100">{Math.floor((profile?.totalReadingTime || 0) / 60)}</p>
                            <p className="text-[10px] font-bold uppercase tracking-widest text-ink-400 dark:text-stone-500 mt-1">Hours</p>
                        </div>
                    </div>
                </div>

                {/* Tabbed Navigation */}
                <div className="flex justify-center md:justify-start border-b border-paper-200 dark:border-stone-800">
                    <button
                        onClick={() => setActiveTab('portfolio')}
                        className={`px-6 py-3 text-xs font-bold uppercase tracking-widest transition-all border-b-2 ${activeTab === 'portfolio' ? 'border-teal-600 text-teal-700 dark:text-teal-500' : 'border-transparent text-ink-400 dark:text-stone-500 hover:text-ink-600 dark:hover:text-stone-300'}`}
                    >
                        <div className="flex items-center gap-2">
                            <BarChart2 size={16} /> Reading Stats
                        </div>
                    </button>
                    <button
                        onClick={() => setActiveTab('settings')}
                        className={`px-6 py-3 text-xs font-bold uppercase tracking-widest transition-all border-b-2 ${activeTab === 'settings' ? 'border-teal-600 text-teal-700 dark:text-teal-500' : 'border-transparent text-ink-400 dark:text-stone-500 hover:text-ink-600 dark:hover:text-stone-300'}`}
                    >
                        <div className="flex items-center gap-2">
                            <Settings size={16} /> Settings
                        </div>
                    </button>
                </div>

                {/* Content Area */}
                <motion.div
                    key={activeTab}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.3 }}
                >
                    {activeTab === 'portfolio' ? (
                        <div className="grid lg:grid-cols-12 gap-8">
                            {/* Main Stats Column */}
                            <div className="lg:col-span-8 space-y-8">
                                {/* Reading Goal Progress */}
                                <div className="card-libra p-8">
                                    <div className="flex items-center justify-between mb-4">
                                        <h3 className="font-serif font-bold text-lg text-ink-900 dark:text-stone-100 flex items-center gap-2">
                                            <Trophy size={20} className="text-amber-500" /> 2026 Reading Challenge
                                        </h3>
                                        <span className="text-sm font-bold text-ink-500 dark:text-stone-400">
                                            {profile?.totalBooksRead || 0} / 50 Books
                                        </span>
                                    </div>
                                    <div className="w-full h-4 bg-paper-100 rounded-full overflow-hidden">
                                        <div
                                            className="h-full bg-gradient-to-r from-teal-500 to-emerald-400 rounded-full"
                                            style={{ width: `${Math.min(((profile?.totalBooksRead || 0) / 50) * 100, 100)}%` }}
                                        />
                                    </div>
                                    <p className="text-xs text-ink-400 mt-2 text-right italic">
                                        {profile?.totalBooksRead >= 50 ? "Goal reached! Amazing!" : "You're on track!"}
                                    </p>
                                </div>

                                {/* Activity Chart */}
                                <div className="card-libra p-8">
                                    <h3 className="font-serif font-bold text-lg text-ink-900 dark:text-stone-100 mb-6 flex items-center gap-2">
                                        <Activity size={20} className="text-teal-600" /> Reading Activity
                                    </h3>
                                    <div className="h-64 w-full">
                                        <ResponsiveContainer width="100%" height="100%">
                                            <BarChart data={weeklyActivity}>
                                                <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#78716c' }} dy={10} />
                                                <Tooltip content={<CustomTooltip />} cursor={{ fill: 'var(--paper-100)' }} />
                                                <Bar dataKey="minutes" fill="#0d9488" radius={[4, 4, 4, 4]} barSize={24} />
                                            </BarChart>
                                        </ResponsiveContainer>
                                    </div>
                                </div>
                            </div>

                            {/* Sidebar Stats */}
                            <div className="lg:col-span-4 space-y-8">
                                {/* Genre Pie Chart */}
                                <div className="card-libra p-8">
                                    <h3 className="font-serif font-bold text-lg text-ink-900 dark:text-stone-100 mb-4 flex items-center gap-2">
                                        <Book size={20} className="text-teal-600" /> Top Genres
                                    </h3>
                                    <div className="h-56">
                                        <ResponsiveContainer width="100%" height="100%">
                                            <PieChart>
                                                <Pie
                                                    data={genreData}
                                                    innerRadius={50}
                                                    outerRadius={70}
                                                    paddingAngle={5}
                                                    dataKey="value"
                                                    stroke="none"
                                                >
                                                    {genreData.map((entry, index) => (
                                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                                    ))}
                                                </Pie>
                                                <Tooltip content={<CustomTooltip />} />
                                            </PieChart>
                                        </ResponsiveContainer>
                                    </div>
                                    <div className="flex flex-wrap justify-center gap-3 mt-2">
                                        {genreData.slice(0, 4).map((genre, index) => (
                                            <div key={genre.name} className="flex items-center gap-1.5">
                                                <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }} />
                                                <span className="text-xs font-bold text-ink-600 dark:text-stone-400">{genre.name}</span>
                                            </div>
                                        ))}
                                    </div>
                                </div>

                                {/* Current Streak */}
                                <div className="card-libra p-6 flex items-center gap-4">
                                    <div className="w-12 h-12 rounded-full bg-amber-50 dark:bg-amber-900/20 flex items-center justify-center text-amber-500">
                                        <Flame size={24} fill="currentColor" />
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold uppercase text-ink-400 dark:text-stone-500 tracking-wider">Current Streak</p>
                                        <p className="text-2xl font-serif font-bold text-ink-900 dark:text-stone-100">{profile?.currentStreak || 0} Days</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="max-w-xl mx-auto">
                            <div className="card-libra p-8 md:p-10">
                                <div className="mb-8 border-b border-paper-200 dark:border-stone-800 pb-4">
                                    <h3 className="text-xl font-bold font-serif text-ink-900 dark:text-stone-100">Profile Settings</h3>
                                    <p className="text-ink-500 dark:text-stone-400 text-sm">Update your personal information and preferences.</p>
                                </div>

                                <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                                    <div>
                                        <label className="text-xs font-bold uppercase tracking-widest text-ink-500 dark:text-stone-400 mb-2 block">Display Name</label>
                                        <input
                                            {...register('name')}
                                            type="text"
                                            className="input-libra w-full"
                                        />
                                        {errors.name && <p className="text-red-500 text-xs mt-1">{errors.name.message}</p>}
                                    </div>

                                    <div>
                                        <label className="text-xs font-bold uppercase tracking-widest text-ink-500 dark:text-stone-400 mb-2 block">Handle</label>
                                        <div className="relative">
                                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-ink-400 dark:text-stone-500 font-bold">@</span>
                                            <input
                                                {...register('username')}
                                                type="text"
                                                className="input-libra w-full pl-8"
                                            />
                                        </div>
                                        {errors.username && <p className="text-red-500 text-xs mt-1">{errors.username.message}</p>}
                                    </div>

                                    <div>
                                        <label className="text-xs font-bold uppercase tracking-widest text-ink-500 dark:text-stone-400 mb-2 block">Email Address</label>
                                        <input
                                            {...register('email')}
                                            type="email"
                                            className="input-libra w-full"
                                        />
                                        {errors.email && <p className="text-red-500 text-xs mt-1">{errors.email.message}</p>}
                                    </div>

                                    <div>
                                        <label className="text-xs font-bold uppercase tracking-widest text-ink-500 dark:text-stone-400 mb-2 block">Avatar URL</label>
                                        <input
                                            {...register('avatar')}
                                            type="text"
                                            placeholder="https://..."
                                            className="input-libra w-full"
                                        />
                                        {errors.avatar && <p className="text-red-500 text-xs mt-1">{errors.avatar.message}</p>}
                                    </div>

                                    <div className="pt-6 border-t border-paper-200 dark:border-stone-800">
                                        <label className="text-xs font-bold uppercase tracking-widest text-ink-500 dark:text-stone-500 mb-2 block">Change Password</label>
                                        <input
                                            {...register('password')}
                                            type="password"
                                            placeholder="New password (leave blank to keep current)"
                                            className="input-libra w-full"
                                        />
                                        {errors.password && <p className="text-red-500 text-xs mt-1">{errors.password.message}</p>}
                                    </div>

                                    <button
                                        type="submit"
                                        disabled={isSubmitting}
                                        className="w-full btn-primary py-3 text-sm font-bold"
                                    >
                                        {isSubmitting ? 'Saving...' : 'Save Changes'}
                                    </button>
                                </form>
                            </div>
                        </div>
                    )}
                </motion.div>
            </div>
        </div>
    );
};

export default ProfilePage;

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import api from '../services/api';
import BookCard from '../components/BookCard';
import { Sparkles, BookOpen, ArrowRight, UserCheck } from 'lucide-react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { useAuthStore } from '../store/authStore';

const RecommendationsPage = () => {
    const { user } = useAuthStore();

    const { data, isLoading, isError } = useQuery({
        queryKey: ['personal-recommendations'],
        queryFn: async () => {
            const res = await api.get('/recommendations/my');
            return res.data;
        },
        enabled: !!user,
        staleTime: 1000 * 60 * 5,
    });

    if (!user) {
        return (
            <div className="min-h-[80vh] flex flex-col items-center justify-center p-6 text-center bg-paper-50">
                <div className="p-4 rounded-full bg-paper-100 mb-6">
                    <UserCheck size={48} className="text-ink-300" />
                </div>
                <h2 className="text-2xl font-serif font-bold text-ink-900 mb-4">Personalized Recommendations</h2>
                <p className="text-ink-600 max-w-md mb-8">
                    Log in to see books tailored specifically to your reading taste and history.
                </p>
                <Link to="/login" className="btn-primary px-8">Sign In</Link>
            </div>
        );
    }

    if (isLoading) {
        return (
            <div className="min-h-screen bg-paper-50 dark:bg-stone-950 pt-12 text-center">
                <div className="animate-pulse space-y-8 max-w-7xl mx-auto px-6">
                    <div className="h-8 bg-paper-200 dark:bg-stone-800 w-1/4 rounded"></div>
                    <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                        {[...Array(5)].map((_, i) => (
                            <div key={i} className="aspect-[2/3] bg-paper-200 dark:bg-stone-800 rounded-md"></div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    const { feed } = data || {};
    const hasData = feed && feed.length > 0;

    return (
        <div className="min-h-screen bg-paper-50 dark:bg-stone-950 pb-20">
            {/* Header */}
            <header className="bg-paper-50 dark:bg-stone-900 border-b border-paper-200 dark:border-stone-800 pt-16 pb-12 px-6 mb-12 relative overflow-hidden">
                <div className="max-w-7xl mx-auto relative z-10">
                    <motion.div
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="max-w-3xl"
                    >
                        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-teal-50 border border-teal-100 text-teal-700 text-xs font-bold uppercase tracking-widest mb-4 dark:bg-stone-800 dark:border-stone-700 dark:text-teal-500">
                            <Sparkles size={14} className="animate-pulse" /> Curated for {user?.name}
                        </div>
                        <h1 className="text-4xl md:text-6xl font-serif font-bold text-ink-900 dark:text-stone-100 mb-6 leading-tight">
                            Recommended <span className="text-teal-600 italic">For You</span>
                        </h1>
                        <p className="text-xl text-ink-600 dark:text-stone-400 font-serif leading-relaxed">
                            Our engine analyzes your library, searches, and reading habits to surface books you'll genuinely love.
                        </p>
                    </motion.div>
                </div>

                {/* Decorative Pattern */}
                <div className="absolute top-0 right-0 w-1/3 h-full opacity-5 pointer-events-none">
                    <Sparkles size={300} className="text-ink-900 dark:text-white" />
                </div>
            </header>

            <div className="max-w-[1400px] mx-auto px-6">
                {!hasData ? (
                    <div className="text-center py-24 bg-white dark:bg-stone-900/50 rounded-3xl border border-dashed border-paper-300">
                        <div className="mb-6 inline-flex p-4 rounded-full bg-paper-50 text-ink-300">
                            <BookOpen size={48} />
                        </div>
                        <h3 className="text-2xl font-serif font-bold text-ink-900 mb-2">Build Your Profile</h3>
                        <p className="text-ink-500 max-w-sm mx-auto mb-8">
                            We don't have enough data yet to give you great recommendations. Start by saving or search for some books you like!
                        </p>
                        <Link to="/explore" className="btn-primary px-8">Explore Books</Link>
                    </div>
                ) : (
                    <div className="space-y-20">
                        {feed.map((section, idx) => (
                            <motion.section
                                key={idx}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: idx * 0.15 }}
                            >
                                <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-8">
                                    <div className="space-y-1">
                                        <div className="flex items-center gap-3">
                                            <h2 className="text-3xl font-serif font-bold text-ink-900">{section.title}</h2>
                                            <span className={`px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded border ${section.type.startsWith('PERSONAL')
                                                ? 'bg-teal-50 text-teal-700 border-teal-100 dark:bg-stone-800 dark:text-teal-400 dark:border-stone-700'
                                                : 'bg-paper-100 text-ink-400 border-paper-200 dark:bg-stone-800 dark:text-stone-500 dark:border-stone-700'
                                                }`}>
                                                {section.type.startsWith('PERSONAL') ? 'Personalized' : 'Discover'}
                                            </span>
                                        </div>
                                        <p className="text-ink-500 font-medium">{section.description}</p>
                                    </div>
                                    <div className="h-0.5 flex-1 bg-paper-100 mx-8 hidden md:block"></div>
                                </div>

                                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-x-6 gap-y-10">
                                    {section.books.map((book) => (
                                        <div key={book.googleBookId || book.openLibraryId || book._id} className="space-y-3">
                                            <BookCard book={book} className="w-full" />
                                            {book.reasons && book.reasons.length > 0 && (
                                                <div className="flex flex-wrap gap-1">
                                                    {book.reasons.map((reason, ridx) => (
                                                        <span key={ridx} className="text-[10px] font-bold uppercase tracking-tighter text-teal-600 py-0.5 px-2 bg-teal-50 dark:bg-stone-800 dark:text-teal-400 rounded ring-1 ring-teal-100 dark:ring-stone-700">
                                                            {reason}
                                                        </span>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </motion.section>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

export default RecommendationsPage;
